INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C1','kor',1,2,'u6',1,'생각을 문장으로 나타내기 — 「위험해요」 같은 느낌에서 그치지 않고 무엇을 어떻게 하면 좋을지와 왜 그런지를 한 문장에 담기, 같은 장면에서도 생각이 다를 수 있음을 알기',ARRAY['2국03-03']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C2','kor',1,2,'u6',2,'문제·해결 방법·자신의 생각 세 칸으로 쓰기 — 눈에 보이는 문제를 찾고, 지금 할 수 있는 해결 방법을 정하고, 까닭을 넣어 자신의 생각을 쓰기, 세 칸의 차례 지키기',ARRAY['2국03-03']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C3','kor',1,2,'u6',4,'시를 읽고 생각을 짧은 문장으로 나타내기 — 시에 나온 혼자일 때와 함께일 때의 모습을 찾고, 둘 다 소중함을 알며, 「좋았어요」에서 그치지 않고 짧은 문장 여러 개로 생각과 다짐을 쓰기',ARRAY['2국05-02']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C4','kor',1,2,'u6',6,'소리와 글자가 다른 낱말 바르게 쓰기 — 받침이 다른 소리로 나도 글자는 그대로 쓰기(솥[솓]·곁[겯]·늪[늡]), 소리가 같아도 뜻이 다른 낱말 가르기(곳·곧, 짓다·짖다), 자음자 이름 바르게 쓰기',ARRAY['2국04-02']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C5','kor',1,2,'u6',8,'뜻이 통하게 덩어리로 띄어 읽기 — 글자마다 끊거나 붙여 읽지 않고 뜻이 이어지는 말끼리 묶어 읽기, 낱말 가운데에서는 쉬지 않기, 뜻이 통하면 쉬는 곳은 여럿일 수 있음을 알기',ARRAY['2국01-04']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C6','kor',1,2,'u6',10,'글의 뜻을 생각하며 쉬어 읽기 — 「누가·무엇이」에 해당하는 말 뒤에서 조금, 그 말이 길면 한 번 더, 문장과 문장 사이에서는 조금 더 쉬기, 이야기의 내용과 차례를 알고 읽기',ARRAY['2국02-01']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C7','kor',1,2,'u6',13,'문장 부호를 살려 읽고 목소리 연극 하기 — 마침표는 차분하게·물음표는 끝을 올려·느낌표는 힘주어 읽기, 역할을 나누어 대사를 읽기, 친구의 읽기를 읽기에 관한 것으로 살피고 귀 기울여 듣기',ARRAY['2국01-04']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('K1-2-u6-C8','kor',1,2,'u6',15,'반대말 알기 — 크다·작다, 덥다·춥다처럼 뜻이 서로 반대인 낱말을 짝지어 문장에 알맞게 쓰기(기초 다지기)',ARRAY['2국04-02']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X01','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C3']::text[],'「위험해요·좋았어요·시끄러워요」처럼 느낌 한마디에서 그치고 무엇을 어떻게 하면 좋을지 말하지 않는다','「그래서 어떻게 하면 좋을까?」 한 번 더 묻기 — 느낌 뒤에 「~하자 / ~하면 좋겠어요」를 붙이게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X02','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C2']::text[],'「하지 마·안 돼」처럼 까닭 없이 하라·하지 말라고만 해서 무엇을 왜 하자는지 전해지지 않는다','「왜?」를 앞에 붙여 보게 하기 — 「~하니까 ~하자」 틀로 고쳐 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X03','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C3']::text[],'같은 장면·같은 시를 보고 나와 생각이 다르면 틀렸다고 한다','「사람마다 걱정하는 것, 마음이 움직이는 곳이 달라요」 — 다른 생각에 「왜 그렇게 생각했어?」 묻게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X04','kor',1,'u6',ARRAY['K1-2-u6-C2']::text[],'문제를 잘못 찾는다(그림·글에 없는 문제를 지어내거나 문제가 아닌 것을 문제로 고르기)','그림·글에서 「무엇이 잘못 쓰이고 있나?」를 손가락으로 짚게 하기 — 보이는 것만 문제로') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X05','kor',1,'u6',ARRAY['K1-2-u6-C2']::text[],'문제를 풀지 못하는 해결 방법을 고른다(아예 하지 않기·버리기·남에게 미루기)','「그렇게 하면 처음 문제가 정말 없어지나요?」 — 지금 내가 바로 할 수 있는 일인지 함께 따져 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X06','kor',1,'u6',ARRAY['K1-2-u6-C2']::text[],'세 칸(문제·해결 방법·자신의 생각) 가운데 하나를 빠뜨리거나 칸의 차례·자리를 뒤섞는다','세 칸 표에 손가락을 짚으며 「무엇이 문제? → 어떻게? → 내 생각과 까닭」 차례로 말하게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X07','kor',1,'u6',ARRAY['K1-2-u6-C1','K1-2-u6-C2','K1-2-u6-C3']::text[],'길게 쓰기·예쁜 글씨·한 문장에 다 이어 쓰기를 잘 쓴 것으로 여긴다(짧은 문장 여러 개·까닭이 중요함을 모름)','긴 한 문장과 짧은 문장 세 개를 나란히 읽어 주고 어느 쪽이 더 잘 들리는지 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X08','kor',1,'u6',ARRAY['K1-2-u6-C3']::text[],'시의 내용을 잘못 읽거나(혼자·함께 모습 뒤바꿈, 시에 없는 것) 시의 줄을 그대로 옮겨 내 생각이라고 한다','시를 한 줄씩 짚으며 「하나일 때 / 모였을 때」 두 칸에 나누어 적게 하고, 생각은 「나도 ~」로 시작해 내 말로 쓰게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X09','kor',1,'u6',ARRAY['K1-2-u6-C3']::text[],'혼자 하는 일과 함께 하는 일을 가리지 못하거나, 둘 가운데 하나만 좋다고 여긴다','「혼자서도 할 수 있는 일 / 여럿이 있어야 되는 일」 두 칸 놀이 — 그리고 「둘 다 소중해요」로 마무리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X10','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'받침의 소리와 글자가 같다고 여겨 소리 나는 대로 쓴다(솥→솓, 곁→겯, 늪→늡)','낱말을 소리 내어 읽은 뒤 글자를 보고 「소리는 [솓], 글자는 솥」 두 줄로 나누어 적게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X11','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'소리가 같으면 같은 낱말·같은 뜻이라고 여긴다(곳·곧, 짓다·짖다)','두 낱말을 그림 카드와 짝짓게 하기 — 소리는 같아도 글자가 다르면 뜻이 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X12','kor',1,'u6',ARRAY['K1-2-u6-C4']::text[],'자음자 이름을 소리 나는 대로 쓴다(치읓→치읃, 히읗→히읃)','「이름 속 받침 자리에 그 자음자가 숨어 있어요」 — ㅊ의 이름 끝 받침에도 ㅊ') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X13','kor',1,'u6',ARRAY['K1-2-u6-C5','K1-2-u6-C6','K1-2-u6-C7']::text[],'글자마다 끊어 읽거나 낱말 가운데에서 쉬어 뜻을 끊는다','낱말 카드를 손으로 덮지 않게 하나씩 통째로 짚으며 읽기 — 낱말은 한 덩어리') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X14','kor',1,'u6',ARRAY['K1-2-u6-C5','K1-2-u6-C6']::text[],'쉬지 않고 붙여 읽어 듣는 사람이 뜻을 잡기 어렵게 한다','한 문장을 두 덩어리 카드로 나누어 놓고 카드 사이에서 숨을 한 번 고르게 하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X15','kor',1,'u6',ARRAY['K1-2-u6-C5']::text[],'쉬어 읽는 곳은 문장마다 딱 한 군데라고 여기거나, 띄어 쓴 곳마다 모두 쉬어야 한다고 여긴다','같은 문장을 두 가지로 쉬어 읽어 보고 「둘 다 뜻이 통하나?」 견주기 — 띄어 쓴 곳마다 쉬면 뚝뚝 끊긴다는 것도 들려주기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X16','kor',1,'u6',ARRAY['K1-2-u6-C6']::text[],'「누가·무엇이」에 해당하는 말을 찾지 못하거나, 그 뒤·문장과 문장 사이에서 쉬어야 함을 모른다','문장마다 「누가?」 물어 답이 되는 말에 동그라미 — 동그라미 뒤에 ∨, 마침표 뒤에 ∨∨') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X17','kor',1,'u6',ARRAY['K1-2-u6-C6','K1-2-u6-C5']::text[],'글이나 이야기의 내용·차례·인물이 한 말을 글과 다르게 읽는다','「그 일이 몇째 줄에 있나요?」 줄을 짚게 하고, 처음·가운데·끝 세 칸에 일을 붙여 보기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X18','kor',1,'u6',ARRAY['K1-2-u6-C7']::text[],'문장 부호를 살리지 않고 읽는다(물음표를 내려 읽기·느낌표를 힘없이·마침표를 올려 읽기)','부호 카드 셋(. ? !)을 들고 같은 말을 세 가지로 읽어 보기 — 끝이 어떻게 달라지나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X19','kor',1,'u6',ARRAY['K1-2-u6-C7','K1-2-u6-C5']::text[],'친구의 읽기를 읽기와 상관없는 것(옷차림·목소리 크기·빠르기)으로 살피거나 겨루고, 틀리면 웃는 등 듣는 예절을 지키지 않는다','「읽기에 대한 것만 말해요」 — 뜻·쉬기·부호 세 가지 살피기 카드를 주고, 듣는 사람은 바라보며 끝까지') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('K1-2-u6-X20','kor',1,'u6',ARRAY['K1-2-u6-C8']::text[],'반대말을 짝짓지 못하거나 뜻이 비슷한 말·상관없는 말을 반대말로 쓴다','몸으로 보여 주기 — 크게·작게, 빠르게·느리게 움직이며 짝 낱말 말하기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#1','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','그림 속 친구에게 해 주고 싶은 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],true,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"그림 속 친구에게 해 주고 싶은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"책 읽는 친구들이 집중할 수 있게 작은 목소리로 말하자.","correct":true},{"t":"시끄러워.","mis":"K1-2-u6-X01"},{"t":"저리 가.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 어떻게 하자는지와 까닭이 함께 있어요.","「시끄러워」는 느낌만, 「저리 가」는 까닭이 없어요.","「~하니까 ~하자」로 말해요."],"asset":{"type":"scene","icon":"📚","text":"도서관에서 한 친구가 큰 소리로 떠들어요"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 그림 속 친구에게 해 주고 싶은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"버스가 멈출 때 넘어질 수 있으니까 손잡이를 꼭 잡자.","correct":true},{"t":"위험해.","mis":"K1-2-u6-X01"},{"t":"그러지 마.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 어떻게 하자는지와 까닭이 함께 있어요.","「위험해」는 느낌만, 「그러지 마」는 까닭이 없어요.","「~하니까 ~하자」로 말해요."],"asset":{"type":"scene","icon":"🚌","text":"버스가 달리는데 한 친구가 손잡이를 잡지 않고 서 있어요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#2','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','느낌에서 한 걸음 더 나아가 생각을 말한 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],true,'{"seq":2,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"느낌에서 한 걸음 더 나아가 생각을 말한 것은 어느 것인가요?","options":[{"t":"먼저 온 친구들이 기다리니까 맨 뒤에 줄을 서자.","correct":true},{"t":"얄미워.","mis":"K1-2-u6-X01"},{"t":"하지 마.","mis":"K1-2-u6-X02"}],"explanation":["어떻게 하자는지(맨 뒤에 서기)와 까닭이 있어요.","「얄미워」는 느낌에서 멈췄어요.","느낌 다음에 「그래서 어떻게?」를 붙여요."],"asset":{"type":"scene","icon":"🍱","text":"급식실에서 한 친구가 줄 앞에 끼어들어요"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 느낌에서 한 걸음 더 나아가 생각을 말한 것은 어느 것인가요?","options":[{"t":"내려오는 친구와 부딪힐 수 있으니까 계단으로 올라가자.","correct":true},{"t":"무서워.","mis":"K1-2-u6-X01"},{"t":"안 돼.","mis":"K1-2-u6-X02"}],"explanation":["어떻게 하자는지와 까닭이 있어요.","「무서워」는 느낌에서 멈췄어요.","느낌 다음에 「그래서 어떻게?」를 붙여요."],"asset":{"type":"scene","icon":"🏃","text":"놀이터에서 한 친구가 미끄럼틀을 거꾸로 올라가요"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#3','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',1,'mc','auto','생각을 문장으로 나타내면 좋은 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07']::text[],false,'{"seq":3,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"생각을 문장으로 나타내면 좋은 까닭은 무엇인가요?","options":[{"t":"무엇을 왜 하자는지 다른 사람이 알 수 있어서","correct":true},{"t":"글씨 연습을 할 수 있어서","mis":"K1-2-u6-X07"},{"t":"말보다 길게 늘일 수 있어서","mis":"K1-2-u6-X07"}],"explanation":["문장으로 나타내면 생각이 또렷하게 전해져요.","글씨 연습이나 길게 늘이는 것이 목적이 아니에요.","무엇을, 어떻게, 왜."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#4','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','문장을 소리 내어 읽을 때 가장 먼저 살필 것은 무엇인가요?',ARRAY['K1-2-u6-X19','K1-2-u6-X14']::text[],false,'{"seq":4,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"문장을 소리 내어 읽을 때 가장 먼저 살필 것은 무엇인가요?","options":[{"t":"듣는 사람이 뜻을 알아듣기 쉽게 읽는지","correct":true},{"t":"친구보다 먼저 다 읽는지","mis":"K1-2-u6-X19"},{"t":"한 번도 숨을 쉬지 않고 읽는지","mis":"K1-2-u6-X14"}],"explanation":["소리 내어 읽는 것은 뜻을 전하려는 거예요.","빨리 끝내기 겨루기가 아니고, 숨 참기도 아니에요.","뜻이 잘 통하는지 들어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#5','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'match','auto','장면과 해 주고 싶은 말을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u6-C1","difficulty":2,"kind":"match","stem":"장면과 해 주고 싶은 말을 선으로 이어 보세요.","pairs":[{"l":"급식실에서 줄 앞에 끼어들어요","r":"기다린 친구들이 속상하니까 맨 뒤에 서자"},{"l":"복도에서 젖은 우산을 털어요","r":"바닥이 미끄러워지니까 우산꽂이 옆에서 털자"},{"l":"도서관에서 큰 소리로 떠들어요","r":"책 읽는 친구에게 방해가 되니까 작게 말하자"}],"mis":"K1-2-u6-X02","explanation":["장면마다 문제가 달라서 할 말도 달라요.","말마다 까닭이 붙어 있어요.","무엇이 문제인지 먼저 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 장면과 해 주고 싶은 말을 선으로 이어 보세요.","pairs":[{"l":"버스에서 손잡이를 잡지 않아요","r":"멈출 때 넘어질 수 있으니까 손잡이를 잡자"},{"l":"미끄럼틀을 거꾸로 올라가요","r":"내려오는 친구와 부딪히니까 계단으로 올라가자"},{"l":"휴지통에 깨끗한 종이가 버려져요","r":"아직 쓸 수 있으니까 연습 종이로 쓰자"}],"explanation":["장면마다 문제가 달라서 할 말도 달라요.","말마다 까닭이 붙어 있어요.","무엇이 문제인지 먼저 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#6','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'mc','auto','「뛰지 마.」라는 말에 더하면 생각이 더 잘 전해지는 것은 무엇인가요?',ARRAY['K1-2-u6-X02']::text[],false,'{"seq":6,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"「뛰지 마.」라는 말에 더하면 생각이 더 잘 전해지는 것은 무엇인가요?","options":[{"t":"왜 뛰면 안 되는지 까닭","correct":true},{"t":"더 크고 무서운 목소리","mis":"K1-2-u6-X02"},{"t":"「절대」라는 말을 여러 번","mis":"K1-2-u6-X02"}],"explanation":["까닭을 들으면 친구가 고개를 끄덕여요.","큰 소리나 「절대」를 늘려도 까닭은 생기지 않아요.","「~하니까 걸어가자」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#7','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'ox','auto','같은 장면을 보고도 친구마다 생각이 다를 수 있어요.',ARRAY['K1-2-u6-X03']::text[],true,'{"seq":7,"concept":"K1-2-u6-C1","difficulty":2,"kind":"ox","stem":"같은 장면을 보고도 친구마다 생각이 다를 수 있어요.","answer":"O","reason_options":[{"t":"사람마다 걱정하는 것이 다르니까","correct":true},{"t":"정답인 생각은 하나뿐이니까","mis":"K1-2-u6-X03"}],"mis":"K1-2-u6-X03","explanation":["넘어질까 걱정, 지나가기 불편함 — 다 생각이에요.","생각에는 하나뿐인 정답이 없어요.","친구 생각도 귀 기울여 들어요."],"variant_rule":{"alt":[{"stem":"친구 생각이 나와 다르면 틀린 생각이에요.","answer":"X","reason_options":[{"t":"생각은 사람마다 다를 수 있으니까","correct":true},{"t":"내 생각이 가장 맞으니까","mis":"K1-2-u6-X03"}],"explanation":["다른 것은 틀린 것이 아니에요.","왜 그렇게 생각했는지 물어봐요.","귀 기울여 들어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#8','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',2,'mc','auto','생각이 잘 드러난 문장은 어느 것인가요?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":8,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"생각이 잘 드러난 문장은 어느 것인가요?","options":[{"t":"도서관에서는 다른 사람이 책에 집중하도록 작은 목소리로 말해요.","correct":true},{"t":"도서관이 좋아요.","mis":"K1-2-u6-X01"},{"t":"도서관은 조용해요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 어떻게 하자는지와 까닭이 다 있어요.","다른 둘은 느낌이나 본 것만 말했어요.","「~하도록 ~해요」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#9','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','「버스가 멈출 때까지 자리에 앉아 있어요.」를 소리 내어 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],true,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"「버스가 멈출 때까지 자리에 앉아 있어요.」를 소리 내어 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻이 이어지는 말끼리 묶어서 또박또박 읽는다","correct":true},{"t":"한 글자씩 끊어서 읽는다","mis":"K1-2-u6-X13"},{"t":"숨 쉬지 않고 한 번에 빨리 읽는다","mis":"K1-2-u6-X14"}],"explanation":["말을 묶어 읽으면 뜻이 잘 전해져요.","한 글자씩 끊거나 쉬지 않으면 알아듣기 어려워요.","덩어리로 읽어요."],"variant_rule":{"alt":[{"stem":"「복도에서는 오른쪽으로 걸어요.」를 소리 내어 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻이 이어지는 말끼리 묶어서 또박또박 읽는다","correct":true},{"t":"글자마다 멈추며 읽는다","mis":"K1-2-u6-X13"},{"t":"처음부터 끝까지 붙여서 빨리 읽는다","mis":"K1-2-u6-X14"}],"explanation":["말을 묶어 읽으면 뜻이 잘 전해져요.","글자마다 멈추거나 붙이면 알아듣기 어려워요.","덩어리로 읽어요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_basic#10','kor',1,2,'u6','L01','g1_2_kor_u6_L01_basic','lesson_basic','K1-2-u6-C1',3,'error','auto','생각이 잘 드러난 문장을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#1','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',2,'mc','auto','그림 속 친구에게 해 주고 싶은 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"그림 속 친구에게 해 주고 싶은 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"바닥이 미끄러워 넘어질 수 있으니까 우산꽂이 옆에서 털자.","correct":true},{"t":"지저분해.","mis":"K1-2-u6-X01"},{"t":"그만해.","mis":"K1-2-u6-X02"}],"explanation":["무엇을 어떻게 할지와 까닭이 함께 있어요.","느낌이나 까닭 없는 말로는 잘 통하지 않아요.","「~하니까 ~하자」."],"asset":{"type":"scene","icon":"☂️","text":"복도에서 한 친구가 젖은 우산을 마구 털어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#2','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C5',2,'ox','auto','문장은 누가 더 빨리 읽나 겨루면서 읽어야 잘 읽은 거예요.',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":2,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"문장은 누가 더 빨리 읽나 겨루면서 읽어야 잘 읽은 거예요.","answer":"X","reason_options":[{"t":"뜻이 잘 통하게 읽는 것이 먼저니까","correct":true},{"t":"빨리 읽으면 시간이 줄어드니까","mis":"K1-2-u6-X19"}],"mis":"K1-2-u6-X19","explanation":["소리 내어 읽기는 겨루기가 아니에요.","빠르기보다 뜻이 잘 통하는지가 중요해요.","듣는 사람을 생각해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#3','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','라온이가 「뭘? 왜?」 하고 되물은 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X02']::text[],true,'{"seq":3,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"라온이가 「뭘? 왜?」 하고 되물은 까닭은 무엇인가요?","options":[{"t":"무엇을 왜 하지 말라는지 알 수 없어서","correct":true},{"t":"수아의 말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"수아가 문장 부호를 안 썼다고 생각해서","mis":"K1-2-u6-X02"}],"explanation":["「그거 하지 마」에는 무엇을, 왜가 빠졌어요.","말이 길어서가 아니라 짧아서 모르는 거예요.","무엇을 왜 — 두 가지를 넣어요."],"asset":{"type":"speech","turns":[{"who":"수아","text":"그거 하지 마."},{"who":"라온","text":"뭘? 왜?"}]},"variant_rule":{"alt":[{"stem":"로아가 「뭐가?」 하고 되물은 까닭은 무엇인가요?","options":[{"t":"무엇이 왜 위험하고 어떻게 하면 좋을지 없어서","correct":true},{"t":"도하의 말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"도하가 웃으며 말해서","mis":"K1-2-u6-X02"}],"explanation":["「위험해!」는 느낌만 있어요.","무엇이 왜, 어떻게가 빠졌어요.","느낌에서 한 걸음 더."],"asset":{"type":"speech","turns":[{"who":"도하","text":"위험해!"},{"who":"로아","text":"뭐가?"}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#4','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','「무서워요.」를 생각이 드러난 문장으로 고친 것은 어느 것인가요?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":4,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"「무서워요.」를 생각이 드러난 문장으로 고친 것은 어느 것인가요?","options":[{"t":"버스가 흔들려 넘어질 수 있으니까 손잡이를 잡아요.","correct":true},{"t":"정말 정말 무서워요.","mis":"K1-2-u6-X01"},{"t":"버스는 무서운 곳이에요.","mis":"K1-2-u6-X01"}],"explanation":["무서운 까닭과 어떻게 할지가 들어갔어요.","「정말」을 늘이거나 바꾸어 말해도 느낌 그대로예요.","까닭 + 어떻게."],"asset":{"type":"scene","icon":"🚌","text":"버스가 달리는데 한 친구가 손잡이를 잡지 않고 서 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#5','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'error','auto','같은 장면을 보고 생각이 다른 친구에게 한 말을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#6','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'mc','auto','무엇이 문제이고 어떻게 하면 좋을지 모두 담은 문장은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],true,'{"seq":6,"concept":"K1-2-u6-C1","difficulty":3,"kind":"mc","stem":"무엇이 문제이고 어떻게 하면 좋을지 모두 담은 문장은 어느 것인가요?","options":[{"t":"책상에 낙서가 있으니까 지우개로 지우고 다시는 쓰지 말자.","correct":true},{"t":"책상이 더러워요.","mis":"K1-2-u6-X01"},{"t":"낙서하지 마.","mis":"K1-2-u6-X02"}],"explanation":["문제(낙서)와 방법(지우고 안 쓰기)이 다 있어요.","「더러워요」는 느낌, 「하지 마」는 까닭이 없어요.","문제 + 어떻게."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 무엇이 문제이고 어떻게 하면 좋을지 모두 담은 문장은 어느 것인가요?","options":[{"t":"신발이 흩어져 있어 찾기 힘드니까 신발장에 나란히 넣자.","correct":true},{"t":"신발장이 엉망이에요.","mis":"K1-2-u6-X01"},{"t":"신발 치워.","mis":"K1-2-u6-X02"}],"explanation":["문제(흩어진 신발)와 방법(나란히 넣기)이 다 있어요.","다른 둘은 느낌이거나 까닭이 없어요.","문제 + 어떻게."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#7','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',3,'match','auto','느낌만 말한 것과, 한 걸음 더 나아간 말을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u6-C1","difficulty":3,"kind":"match","stem":"느낌만 말한 것과, 한 걸음 더 나아간 말을 선으로 이어 보세요.","pairs":[{"l":"지저분해요.","r":"휴지가 떨어져 있으니까 주워서 버려요."},{"l":"시끄러워요.","r":"친구가 책을 읽으니까 작게 말해요."},{"l":"위험해요.","r":"계단에서 밀면 넘어지니까 한 줄로 내려가요."}],"mis":"K1-2-u6-X01","explanation":["느낌마다 그 까닭과 할 일을 이었어요.","지저분함은 휴지, 시끄러움은 소리, 위험은 넘어짐.","같은 일을 가리키는 짝을 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#8','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'sa','auto','다음 말에서 빠진 것을 두 글자로 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#9','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'essay','teacher','그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 먼저 와서 기다린 친구들이 있으니까 맨 뒤로 가서 줄을 서자. — 할 일과 까닭이 함께 있으면 맞아요.","scoring_points":["무엇을 어떻게 하자는지 있는가","까닭이 있는가","나무라지 않고 친구가 받아들이기 쉬운 말인가"]},"explanation":["할 일 + 까닭.","「하지 마」 대신 「~하자」.","친구가 고개를 끄덕일 말."],"asset":{"type":"scene","icon":"🍱","text":"급식실에서 한 친구가 줄 앞에 끼어들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L01_challenge#10','kor',1,2,'u6','L01','g1_2_kor_u6_L01_challenge','lesson_challenge','K1-2-u6-C1',4,'essay','teacher','우리 교실에서 고치고 싶은 모습 하나를 떠올려, 무엇이 문제이고 어떻게 하면 좋을지 까닭을 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"우리 교실에서 고치고 싶은 모습 하나를 떠올려, 무엇이 문제이고 어떻게 하면 좋을지 까닭을 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 쉬는 시간에 의자를 넣지 않아 지나가기 힘드니까 일어나면 의자를 책상 밑에 넣으면 좋겠어요. — 문제·방법·까닭이 있으면 맞아요(어떤 모습이든 좋아요).","scoring_points":["문제가 드러나는가","어떻게 하면 좋을지 있는가","까닭이 있는가"]},"explanation":["문제 + 방법 + 까닭.","느낌에서 멈추지 않아요.","우리 교실에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#1','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',1,'mc','auto','생각을 세 칸으로 쓸 때 첫째 칸에 쓰는 것은 무엇인가요?',ARRAY['K1-2-u6-X06']::text[],true,'{"seq":1,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"생각을 세 칸으로 쓸 때 첫째 칸에 쓰는 것은 무엇인가요?","options":[{"t":"무엇이 문제인지","correct":true},{"t":"어떻게 해결할지","mis":"K1-2-u6-X06"},{"t":"내 생각과 까닭","mis":"K1-2-u6-X06"}],"explanation":["첫째 칸은 문제예요.","해결 방법은 둘째, 자신의 생각은 셋째예요.","문제 → 해결 방법 → 자신의 생각."],"variant_rule":{"alt":[{"stem":"생각을 세 칸으로 쓸 때 셋째 칸에 쓰는 것은 무엇인가요?","options":[{"t":"까닭을 넣은 자신의 생각","correct":true},{"t":"무엇이 문제인지","mis":"K1-2-u6-X06"},{"t":"어떻게 해결할지","mis":"K1-2-u6-X06"}],"explanation":["셋째 칸은 자신의 생각이에요.","문제는 첫째, 해결 방법은 둘째예요.","문제 → 해결 방법 → 자신의 생각."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#2','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',1,'mc','auto','지안이가 찾은 문제는 무엇인가요?',ARRAY['K1-2-u6-X04']::text[],true,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"지안이가 찾은 문제는 무엇인가요?","options":[{"t":"에어컨을 켰는데 창문이 열려 있다","correct":true},{"t":"에어컨이 고장 났다","mis":"K1-2-u6-X04"},{"t":"교실이 너무 춥다","mis":"K1-2-u6-X04"}],"explanation":["「문제」 칸에 그렇게 썼어요.","고장이나 추위는 글에 없어요.","첫째 줄을 봐요."],"asset":{"type":"passage","lines":["문제: 에어컨을 켰는데 창문이 열려 있어요.","해결 방법: 에어컨을 켤 때에는 창문을 닫아요.","자신의 생각: 시원한 바람이 밖으로 빠져나가니까 창문을 닫으면 좋겠어요."],"title":"지안이가 쓴 세 칸 생각"},"variant_rule":{"alt":[{"stem":"서진이가 찾은 문제는 무엇인가요?","options":[{"t":"손을 닦을 때 화장지를 길게 많이 뜯는다","correct":true},{"t":"화장지가 다 떨어졌다","mis":"K1-2-u6-X04"},{"t":"손을 씻지 않는다","mis":"K1-2-u6-X04"}],"explanation":["「문제」 칸에 그렇게 썼어요.","화장지가 떨어졌다거나 손을 안 씻는다는 말은 없어요.","첫째 줄을 봐요."],"asset":{"type":"passage","lines":["문제: 손을 닦을 때 화장지를 길게 많이 뜯어요.","해결 방법: 필요한 만큼만 뜯어 써요.","자신의 생각: 버려지는 화장지가 줄어드니까 조금씩 쓰면 좋겠어요."],"title":"서진이가 쓴 세 칸 생각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#3','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',1,'mc','auto','로아가 쓴 해결 방법은 무엇인가요?',ARRAY['K1-2-u6-X05']::text[],true,'{"seq":3,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"로아가 쓴 해결 방법은 무엇인가요?","options":[{"t":"다 쓰면 바로 뚜껑을 닫는다","correct":true},{"t":"사인펜을 쓰지 않는다","mis":"K1-2-u6-X05"},{"t":"새 사인펜을 산다","mis":"K1-2-u6-X05"}],"explanation":["「해결 방법」 칸에 그렇게 썼어요.","안 쓰거나 새로 사면 문제가 풀리지 않아요.","둘째 줄을 봐요."],"asset":{"type":"passage","lines":["문제: 사인펜 뚜껑을 열어 둔 채 놀러 나가요.","해결 방법: 다 쓰면 바로 뚜껑을 닫아요.","자신의 생각: 사인펜이 마르면 더 쓸 수 없으니까 뚜껑을 꼭 닫으면 좋겠어요."],"title":"로아가 쓴 세 칸 생각"},"variant_rule":{"alt":[{"stem":"해린이가 쓴 해결 방법은 무엇인가요?","options":[{"t":"현관에서 물기를 털고 우산꽂이에 꽂는다","correct":true},{"t":"비 오는 날에는 학교에 오지 않는다","mis":"K1-2-u6-X05"},{"t":"우산을 버린다","mis":"K1-2-u6-X05"}],"explanation":["「해결 방법」 칸에 그렇게 썼어요.","학교에 안 오거나 버리는 것은 방법이 아니에요.","둘째 줄을 봐요."],"asset":{"type":"passage","lines":["문제: 젖은 우산을 털지 않고 교실까지 들고 와요.","해결 방법: 현관에서 물기를 털고 우산꽂이에 꽂아요.","자신의 생각: 교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요."],"title":"해린이가 쓴 세 칸 생각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#4','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',1,'mc','auto','아직 쓸 수 있는데 버려지는 것은 어느 것인가요?',ARRAY['K1-2-u6-X04']::text[],true,'{"seq":4,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"아직 쓸 수 있는데 버려지는 것은 어느 것인가요?","options":[{"t":"조금 닳은 지우개","correct":true},{"t":"구멍 나서 물이 새는 물통","mis":"K1-2-u6-X04"},{"t":"다 써서 나오지 않는 풀","mis":"K1-2-u6-X04"}],"explanation":["조금 닳아도 지우개는 아직 잘 지워져요.","새는 물통, 다 쓴 풀은 더 쓸 수 없어요.","아직 쓸 수 있는지 살펴요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 아직 쓸 수 있는데 버려지는 것은 어느 것인가요?","options":[{"t":"뒷면이 깨끗한 연습 종이","correct":true},{"t":"찢어져 글씨가 안 보이는 쪽지","mis":"K1-2-u6-X04"},{"t":"바닥이 깨진 컵","mis":"K1-2-u6-X04"}],"explanation":["뒷면에 또 쓸 수 있어요.","찢어진 쪽지, 깨진 컵은 쓸 수 없어요.","아직 쓸 수 있는지 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#5','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',2,'match','auto','문제와 알맞은 해결 방법을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u6-C2","difficulty":2,"kind":"match","stem":"문제와 알맞은 해결 방법을 선으로 이어 보세요.","pairs":[{"l":"에어컨을 켰는데 창문이 열려 있어요","r":"창문을 닫아요"},{"l":"화장지를 길게 많이 뜯어요","r":"필요한 만큼만 뜯어요"},{"l":"사인펜 뚜껑을 열어 두어요","r":"쓰고 나면 바로 닫아요"}],"mis":"K1-2-u6-X05","explanation":["문제마다 그 문제를 없애는 방법이 짝이에요.","열린 창문은 닫고, 많이 뜯으면 조금만.","방법이 문제를 풀어 주는지 봐요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 문제와 알맞은 해결 방법을 선으로 이어 보세요.","pairs":[{"l":"크레파스를 바닥에 두어요","r":"다 쓰면 상자에 넣어요"},{"l":"젖은 우산을 교실까지 들고 와요","r":"현관에서 털고 꽂아요"},{"l":"물을 따르고 남겨 버려요","r":"마실 만큼만 따라요"}],"explanation":["문제마다 그 문제를 없애는 방법이 짝이에요.","바닥엔 상자, 젖은 우산엔 현관, 남긴 물엔 조금만.","방법이 문제를 풀어 주는지 봐요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#6','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',2,'mc','auto','지안이의 「자신의 생각」에 들어 있는 까닭은 무엇인가요?',ARRAY['K1-2-u6-X04']::text[],true,'{"seq":6,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"지안이의 「자신의 생각」에 들어 있는 까닭은 무엇인가요?","options":[{"t":"시원한 바람이 밖으로 빠져나가서","correct":true},{"t":"창문이 너무 커서","mis":"K1-2-u6-X04"},{"t":"에어컨이 새것이라서","mis":"K1-2-u6-X04"}],"explanation":["「~빠져나가니까」가 까닭이에요.","창문 크기나 새것이라는 말은 없어요.","「~니까」 앞을 봐요."],"asset":{"type":"passage","lines":["문제: 에어컨을 켰는데 창문이 열려 있어요.","해결 방법: 에어컨을 켤 때에는 창문을 닫아요.","자신의 생각: 시원한 바람이 밖으로 빠져나가니까 창문을 닫으면 좋겠어요."],"title":"지안이가 쓴 세 칸 생각"},"variant_rule":{"alt":[{"stem":"로아의 「자신의 생각」에 들어 있는 까닭은 무엇인가요?","options":[{"t":"사인펜이 마르면 더 쓸 수 없어서","correct":true},{"t":"사인펜 색이 예뻐서","mis":"K1-2-u6-X04"},{"t":"뚜껑이 잘 안 닫혀서","mis":"K1-2-u6-X04"}],"explanation":["「~쓸 수 없으니까」가 까닭이에요.","색이나 뚜껑이 안 닫힌다는 말은 없어요.","「~니까」 앞을 봐요."],"asset":{"type":"passage","lines":["문제: 사인펜 뚜껑을 열어 둔 채 놀러 나가요.","해결 방법: 다 쓰면 바로 뚜껑을 닫아요.","자신의 생각: 사인펜이 마르면 더 쓸 수 없으니까 뚜껑을 꼭 닫으면 좋겠어요."],"title":"로아가 쓴 세 칸 생각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#7','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',2,'ox','auto','해결 방법은 지금 바로 내가 할 수 있는 일로 쓰면 좋아요.',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":7,"concept":"K1-2-u6-C2","difficulty":2,"kind":"ox","stem":"해결 방법은 지금 바로 내가 할 수 있는 일로 쓰면 좋아요.","answer":"O","reason_options":[{"t":"할 수 있어야 문제가 실제로 풀리니까","correct":true},{"t":"어려운 방법일수록 멋지니까","mis":"K1-2-u6-X05"}],"mis":"K1-2-u6-X05","explanation":["내가 할 수 있는 일이어야 해요.","멋져 보이는 것보다 실제로 되는 것이 중요해요.","오늘 바로 할 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#8','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',2,'mc','auto','내 생각을 잘 전하려면 문장에 무엇이 꼭 들어가야 하나요?',ARRAY['K1-2-u6-X07']::text[],false,'{"seq":8,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"내 생각을 잘 전하려면 문장에 무엇이 꼭 들어가야 하나요?","options":[{"t":"왜 그렇게 생각했는지 까닭","correct":true},{"t":"여러 줄로 길게 늘인 말","mis":"K1-2-u6-X07"},{"t":"꾸미는 말을 많이 넣은 말","mis":"K1-2-u6-X07"}],"explanation":["까닭이 있어야 생각이 통해요.","길이나 꾸밈말은 중요하지 않아요.","「~니까」를 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#9','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',2,'mc','auto','서진이의 세 칸 생각에서 「해결 방법」 칸은 어느 것인가요?',ARRAY['K1-2-u6-X06']::text[],true,'{"seq":9,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"서진이의 세 칸 생각에서 「해결 방법」 칸은 어느 것인가요?","options":[{"t":"필요한 만큼만 뜯어 써요.","correct":true},{"t":"손을 닦을 때 화장지를 길게 많이 뜯어요.","mis":"K1-2-u6-X06"},{"t":"버려지는 화장지가 줄어드니까 조금씩 쓰면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이 해결 방법이에요.","첫째는 문제, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 손을 닦을 때 화장지를 길게 많이 뜯어요.","해결 방법: 필요한 만큼만 뜯어 써요.","자신의 생각: 버려지는 화장지가 줄어드니까 조금씩 쓰면 좋겠어요."],"title":"서진이가 쓴 세 칸 생각"},"variant_rule":{"alt":[{"stem":"해린이의 세 칸 생각에서 「문제」 칸은 어느 것인가요?","options":[{"t":"젖은 우산을 털지 않고 교실까지 들고 와요.","correct":true},{"t":"현관에서 물기를 털고 우산꽂이에 꽂아요.","mis":"K1-2-u6-X06"},{"t":"교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["첫째 칸이 문제예요.","둘째는 해결 방법, 셋째는 자신의 생각이에요.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 젖은 우산을 털지 않고 교실까지 들고 와요.","해결 방법: 현관에서 물기를 털고 우산꽂이에 꽂아요.","자신의 생각: 교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요."],"title":"해린이가 쓴 세 칸 생각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_basic#10','kor',1,2,'u6','L02','g1_2_kor_u6_L02_basic','lesson_basic','K1-2-u6-C2',3,'error','auto','도하가 쓴 세 칸 생각에서 고쳐야 할 칸은 어느 것이고, 왜 그런가요?',ARRAY['K1-2-u6-X05','K1-2-u6-X04','K1-2-u6-X02']::text[],false,'{"seq":10,"concept":"K1-2-u6-C2","difficulty":3,"kind":"error","stem":"도하가 쓴 세 칸 생각에서 고쳐야 할 칸은 어느 것이고, 왜 그런가요?","options":[{"t":"해결 방법 — 물을 마시지 않으면 물을 남기는 문제가 풀리지 않아요","correct":true,"mis_target":"K1-2-u6-X05"},{"t":"문제 — 물을 남기는 것은 문제가 아니에요","mis":"K1-2-u6-X04"},{"t":"자신의 생각 — 까닭이 들어가면 안 돼요","mis":"K1-2-u6-X02"}],"explanation":["물을 안 마시는 것은 방법이 아니에요.","문제와 자신의 생각은 잘 썼어요.","「마실 만큼만 따라요」로 고쳐요."],"asset":{"type":"passage","lines":["문제: 물을 마시고 컵에 물을 남겨 버려요.","해결 방법: 물을 마시지 않아요.","자신의 생각: 남긴 물이 그냥 버려지니까 마실 만큼만 따르면 좋겠어요."],"title":"도하가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#1','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',2,'mc','auto','해린이가 걱정한 것은 무엇인가요?',ARRAY['K1-2-u6-X04']::text[],false,'{"seq":1,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"해린이가 걱정한 것은 무엇인가요?","options":[{"t":"교실 바닥이 미끄러워 넘어질 수 있는 것","correct":true},{"t":"우산 색이 마음에 들지 않는 것","mis":"K1-2-u6-X04"},{"t":"우산꽂이가 너무 작은 것","mis":"K1-2-u6-X04"}],"explanation":["「자신의 생각」에 걱정이 들어 있어요.","우산 색이나 크기 이야기는 없어요.","「~니까」 앞을 봐요."],"asset":{"type":"passage","lines":["문제: 젖은 우산을 털지 않고 교실까지 들고 와요.","해결 방법: 현관에서 물기를 털고 우산꽂이에 꽂아요.","자신의 생각: 교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요."],"title":"해린이가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#2','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',2,'mc','auto','시온이의 세 칸 생각에서 빠진 칸은 무엇인가요?',ARRAY['K1-2-u6-X06']::text[],true,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"시온이의 세 칸 생각에서 빠진 칸은 무엇인가요?","options":[{"t":"자신의 생각","correct":true},{"t":"문제","mis":"K1-2-u6-X06"},{"t":"해결 방법","mis":"K1-2-u6-X06"}],"explanation":["문제와 해결 방법만 있어요.","까닭을 넣은 자신의 생각이 빠졌어요.","세 칸을 하나씩 짚어요."],"asset":{"type":"passage","lines":["문제: 크레파스를 쓰고 바닥에 그냥 두어요.","해결 방법: 다 쓰면 크레파스 상자에 넣어요."],"title":"시온이가 쓴 세 칸 생각"},"variant_rule":{"alt":[{"stem":"수아의 세 칸 생각에서 빠진 칸은 무엇인가요?","options":[{"t":"문제","correct":true},{"t":"해결 방법","mis":"K1-2-u6-X06"},{"t":"자신의 생각","mis":"K1-2-u6-X06"}],"explanation":["해결 방법과 자신의 생각만 있어요.","무엇이 문제인지가 빠졌어요.","세 칸을 하나씩 짚어요."],"asset":{"type":"passage","lines":["해결 방법: 신발을 신발장 칸에 나란히 넣어요.","자신의 생각: 다음 친구가 신발을 찾기 쉬우니까 나란히 넣으면 좋겠어요."],"title":"수아가 쓴 세 칸 생각"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#3','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'error','auto','세 칸 생각을 이렇게 썼어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#4','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'mc','auto','도하의 해결 방법을 고친다면 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":4,"concept":"K1-2-u6-C2","difficulty":3,"kind":"mc","stem":"도하의 해결 방법을 고친다면 가장 알맞은 것은 어느 것인가요?","options":[{"t":"마실 만큼만 컵에 따라요.","correct":true},{"t":"물을 아예 마시지 않아요.","mis":"K1-2-u6-X05"},{"t":"남은 물은 친구 컵에 부어요.","mis":"K1-2-u6-X05"}],"explanation":["마실 만큼만 따르면 남는 물이 없어요.","안 마시거나 남에게 미루면 문제가 그대로예요.","문제가 정말 없어지나요?"],"asset":{"type":"passage","lines":["문제: 물을 마시고 컵에 물을 남겨 버려요.","해결 방법: 물을 마시지 않아요.","자신의 생각: 남긴 물이 그냥 버려지니까 마실 만큼만 따르면 좋겠어요."],"title":"도하가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#5','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'mc','auto','그림에서 찾을 수 있는 문제로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X04']::text[],false,'{"seq":5,"concept":"K1-2-u6-C2","difficulty":3,"kind":"mc","stem":"그림에서 찾을 수 있는 문제로 알맞은 것은 어느 것인가요?","options":[{"t":"아직 쓸 수 있는 종이가 버려지고 있다","correct":true},{"t":"휴지통이 너무 크다","mis":"K1-2-u6-X04"},{"t":"종이가 하얀색이다","mis":"K1-2-u6-X04"}],"explanation":["깨끗한 종이는 아직 쓸 수 있어요.","휴지통 크기나 종이 색은 문제가 아니에요.","무엇이 아깝게 쓰이나요?"],"asset":{"type":"scene","icon":"🗑️","text":"휴지통에 아직 깨끗한 종이가 잔뜩 버려져 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#6','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'ox','auto','「연필이 짧아요.」는 세 칸 가운데 「자신의 생각」 칸에 알맞은 문장이에요.',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":6,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"「연필이 짧아요.」는 세 칸 가운데 「자신의 생각」 칸에 알맞은 문장이에요.","answer":"X","reason_options":[{"t":"무엇을 왜 하자는지 없이 보이는 것만 말했으니까","correct":true},{"t":"연필에 대한 말이니 어느 칸이든 괜찮으니까","mis":"K1-2-u6-X06"}],"mis":"K1-2-u6-X01","explanation":["보이는 것만 말했어요.","자신의 생각에는 할 일과 까닭이 있어야 해요.","「~니까 ~하면 좋겠어요」."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#7','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',3,'mc','auto','「자신의 생각」 칸으로 가장 잘 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],true,'{"seq":7,"concept":"K1-2-u6-C2","difficulty":3,"kind":"mc","stem":"「자신의 생각」 칸으로 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"사인펜이 마르면 다시 쓸 수 없으니까 쓰고 나면 바로 뚜껑을 닫으면 좋겠어요.","correct":true},{"t":"사인펜이 좋아요.","mis":"K1-2-u6-X01"},{"t":"뚜껑을 닫으면 좋겠어요.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","「좋아요」는 느낌, 셋째는 까닭이 없어요.","「~니까 ~면 좋겠어요」."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 「자신의 생각」 칸으로 가장 잘 쓴 것은 어느 것인가요?","options":[{"t":"다음 친구가 찾기 쉬우니까 신발을 나란히 넣으면 좋겠어요.","correct":true},{"t":"신발장이 예뻐요.","mis":"K1-2-u6-X01"},{"t":"신발을 넣으면 좋겠어요.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","「예뻐요」는 느낌, 셋째는 까닭이 없어요.","「~니까 ~면 좋겠어요」."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#8','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'sa','auto','세 칸 생각의 칸 이름을 차례대로 쓸 때 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#9','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'essay','teacher','교실이나 집에서 아깝게 버려지는 것을 하나 떠올려, 문제·해결 방법·자신의 생각 세 칸으로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C2","difficulty":4,"kind":"essay","stem":"교실이나 집에서 아깝게 버려지는 것을 하나 떠올려, 문제·해결 방법·자신의 생각 세 칸으로 쓰세요.","answer_guide":{"answer":"예: 문제 — 크레파스 상자가 망가져 크레파스를 버려요. 해결 방법 — 빈 상자에 담아 다시 써요. 자신의 생각 — 크레파스는 아직 잘 그려지니까 버리지 않으면 좋겠어요. — 세 칸이 차례대로 있고 생각에 까닭이 있으면 맞아요.","scoring_points":["세 칸이 모두 있는가","해결 방법이 문제를 실제로 풀 수 있는가","자신의 생각에 까닭이 있는가"]},"explanation":["문제 → 해결 방법 → 자신의 생각.","지금 할 수 있는 방법으로.","까닭을 꼭 넣어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L02_challenge#10','kor',1,2,'u6','L02','g1_2_kor_u6_L02_challenge','lesson_challenge','K1-2-u6-C2',4,'essay','teacher','도하의 세 칸 생각에서 해결 방법을 알맞게 고쳐 쓰고, 그렇게 고친 까닭을 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C2","difficulty":4,"kind":"essay","stem":"도하의 세 칸 생각에서 해결 방법을 알맞게 고쳐 쓰고, 그렇게 고친 까닭을 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 해결 방법 — 마실 만큼만 컵에 따라요. 까닭 — 물을 안 마시면 목이 마르고, 조금씩 따르면 남는 물이 없기 때문이에요. — 문제를 실제로 푸는 방법과 까닭이 있으면 맞아요.","scoring_points":["고친 방법이 문제(물을 남김)를 풀 수 있는가","지금 할 수 있는 방법인가","고친 까닭이 있는가"]},"explanation":["안 마시기는 방법이 아니에요.","남지 않게 하는 방법을 찾아요.","까닭을 함께 써요."],"asset":{"type":"passage","lines":["문제: 물을 마시고 컵에 물을 남겨 버려요.","해결 방법: 물을 마시지 않아요.","자신의 생각: 남긴 물이 그냥 버려지니까 마실 만큼만 따르면 좋겠어요."],"title":"도하가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#1','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','이 시에서 돌 하나가 혼자 있는 모습을 그린 줄은 어느 것인가요?',ARRAY['K1-2-u6-X08']::text[],true,'{"seq":1,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 시에서 돌 하나가 혼자 있는 모습을 그린 줄은 어느 것인가요?","options":[{"t":"혼자서도 물소리를 들으며 앉아 있어요","correct":true},{"t":"친구들이 건너는 길이 되어요","mis":"K1-2-u6-X08"},{"t":"돌이 줄지어 놓이면","mis":"K1-2-u6-X08"}],"explanation":["둘째 줄이 돌 하나의 모습이에요.","셋째·넷째 줄은 돌이 모였을 때예요.","「하나」와 「줄지어」를 나누어 봐요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"},"variant_rule":{"alt":[{"stem":"이 시에서 크레파스 하나가 혼자 그리는 모습을 그린 줄은 어느 것인가요?","options":[{"t":"사과 하나를 동그랗게 그려요","correct":true},{"t":"하늘 가득 무지개를 그려요","mis":"K1-2-u6-X08"},{"t":"크레파스 일곱이 모이면","mis":"K1-2-u6-X08"}],"explanation":["둘째 줄이 크레파스 하나의 모습이에요.","셋째·넷째 줄은 모였을 때예요.","「혼자서」와 「모이면」을 나누어 봐요."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#2','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','시에서 돌이 줄지어 놓이면 무엇이 되나요?',ARRAY['K1-2-u6-X08']::text[],true,'{"seq":2,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"시에서 돌이 줄지어 놓이면 무엇이 되나요?","options":[{"t":"친구들이 건너는 길","correct":true},{"t":"냇물 위의 큰 산","mis":"K1-2-u6-X08"},{"t":"시원한 물소리","mis":"K1-2-u6-X08"}],"explanation":["「친구들이 건너는 길이 되어요」예요.","산은 시에 없고, 물소리는 돌 하나가 듣는 것이에요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"},"variant_rule":{"alt":[{"stem":"시에서 나뭇잎이 모이고 모이면 무엇이 되나요?","options":[{"t":"시원한 그늘","correct":true},{"t":"빙그르르 춤","mis":"K1-2-u6-X08"},{"t":"커다란 바람","mis":"K1-2-u6-X08"}],"explanation":["「시원한 그늘이 되어요」예요.","춤은 나뭇잎 하나가 추는 것이에요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#3','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','시를 읽고 생각을 나타낸 문장으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"시를 읽고 생각을 나타낸 문장으로 알맞은 것은 어느 것인가요?","options":[{"t":"나도 친구들과 힘을 모아 큰 그림을 그려 보고 싶어요.","correct":true},{"t":"재미있어요.","mis":"K1-2-u6-X01"},{"t":"크레파스.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 하고 싶은지 생각이 드러나요.","「재미있어요」나 낱말 하나로는 생각을 알 수 없어요.","「나도 ~하고 싶어요」."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#4','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',1,'mc','auto','시를 읽고 생각을 나타내는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X07']::text[],false,'{"seq":4,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"시를 읽고 생각을 나타내는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"무엇이 어땠는지 짧은 문장 여러 개로 쓴다","correct":true},{"t":"「좋았어요」 한마디로 쓴다","mis":"K1-2-u6-X01"},{"t":"모든 생각을 한 문장에 길게 이어 쓴다","mis":"K1-2-u6-X07"}],"explanation":["짧은 문장 여러 개가 분명해요.","한마디는 모자라고, 너무 긴 문장은 뜻이 흐려져요.","짧게, 여러 개로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#5','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'match','auto','시에 나온 낱말과 알맞은 뜻을 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u6-C3","difficulty":2,"kind":"match","stem":"시에 나온 낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"징검돌","r":"냇물을 건너려고 띄엄띄엄 놓은 돌"},{"l":"줄지어","r":"여럿이 줄을 이루어"},{"l":"혼자서","r":"아무와도 함께하지 않고"}],"mis":"K1-2-u6-X08","explanation":["징검돌은 냇물을 건너는 돌이에요.","줄지어는 줄을 이루어, 혼자서는 홀로.","시에서 쓰인 자리를 떠올려요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 시에 나온 낱말과 알맞은 뜻을 선으로 이어 보세요.","pairs":[{"l":"소복소복","r":"많이 쌓여 볼록한 모양"},{"l":"살며시","r":"소리 나지 않게 가만히"},{"l":"눈송이","r":"작은 송이로 내리는 눈"}],"explanation":["소복소복은 많이 쌓인 모양이에요.","살며시는 가만히, 눈송이는 송이로 내리는 눈.","시에서 쓰인 자리를 떠올려요."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#6','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'ox','auto','혼자 하는 일보다 함께 하는 일이 언제나 더 좋아요.',ARRAY['K1-2-u6-X09']::text[],true,'{"seq":6,"concept":"K1-2-u6-C3","difficulty":2,"kind":"ox","stem":"혼자 하는 일보다 함께 하는 일이 언제나 더 좋아요.","answer":"X","reason_options":[{"t":"혼자일 때도 함께일 때도 소중하니까","correct":true},{"t":"여럿이 모여야만 빛이 나니까","mis":"K1-2-u6-X09"}],"mis":"K1-2-u6-X09","explanation":["둘 다 소중해요.","시도 돌 하나와 줄지은 돌을 모두 그렸어요.","어느 하나만 좋은 것이 아니에요."],"variant_rule":{"alt":[{"stem":"시 「징검돌」의 돌 하나는 혼자라서 쓸모가 없어요.","answer":"X","reason_options":[{"t":"혼자서도 물소리를 들으며 제자리를 지키니까","correct":true},{"t":"모여야만 쓸모가 생기니까","mis":"K1-2-u6-X09"}],"explanation":["돌 하나도 제 모습이 있어요.","시는 혼자일 때도 그렸어요.","둘 다 소중해요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#7','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'mc','auto','여럿이 함께해야 더 잘되는 일은 어느 것인가요?',ARRAY['K1-2-u6-X09']::text[],true,'{"seq":7,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"여럿이 함께해야 더 잘되는 일은 어느 것인가요?","options":[{"t":"모둠 친구들과 큰 그림 완성하기","correct":true},{"t":"혼자 이 닦기","mis":"K1-2-u6-X09"},{"t":"내 이름 쓰기","mis":"K1-2-u6-X09"}],"explanation":["큰 그림은 여럿이 나누어 그리면 잘돼요.","이 닦기, 이름 쓰기는 혼자 하는 일이에요.","여럿이 있어야 되는 일을 찾아요."],"variant_rule":{"alt":[{"stem":"혼자서도 잘할 수 있는 일은 어느 것인가요?","options":[{"t":"내 책상 서랍 정리하기","correct":true},{"t":"긴 줄넘기를 함께 넘기","mis":"K1-2-u6-X09"},{"t":"운동회 박 터뜨리기","mis":"K1-2-u6-X09"}],"explanation":["서랍 정리는 나 혼자 시작할 수 있어요.","긴 줄넘기, 박 터뜨리기는 여럿이 해요.","나 혼자 할 수 있는 일을 찾아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#8','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'mc','auto','시를 읽고 우리 반을 위한 다짐을 쓴 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01']::text[],false,'{"seq":8,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시를 읽고 우리 반을 위한 다짐을 쓴 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"쉬는 시간이 끝나면 교실 바닥의 쓰레기를 내가 먼저 줍겠어요.","correct":true},{"t":"잘하겠어요.","mis":"K1-2-u6-X01"},{"t":"우리 반은 좋아요.","mis":"K1-2-u6-X01"}],"explanation":["무엇을 언제 할지 분명해요.","「잘하겠어요」만으로는 무엇을 할지 몰라요.","언제 + 무엇을."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#9','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',2,'mc','auto','이 시에서 눈송이가 쌓여 생긴 것은 무엇인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":9,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"이 시에서 눈송이가 쌓여 생긴 것은 무엇인가요?","options":[{"t":"하얀 눈사람","correct":true},{"t":"내 손등","mis":"K1-2-u6-X08"},{"t":"하얀 구름","mis":"K1-2-u6-X08"}],"explanation":["「마당에 하얀 눈사람이 생겨요」예요.","손등은 눈송이 하나가 앉은 곳이에요.","마지막 줄을 봐요."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_basic#10','kor',1,2,'u6','L04','g1_2_kor_u6_L04_basic','lesson_basic','K1-2-u6-C3',3,'error','auto','시를 읽고 쓴 생각 문장을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#1','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',2,'mc','auto','시에서 나뭇잎 하나가 혼자 하는 일은 무엇인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":1,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시에서 나뭇잎 하나가 혼자 하는 일은 무엇인가요?","options":[{"t":"바람을 타고 춤을 춘다","correct":true},{"t":"시원한 그늘이 된다","mis":"K1-2-u6-X08"},{"t":"나무를 높이 키운다","mis":"K1-2-u6-X08"}],"explanation":["둘째 줄이에요.","그늘은 나뭇잎이 모였을 때예요.","「하나가」 다음 줄을 봐요."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#2','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',2,'mc','auto','생각을 더 분명하게 나타낸 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X01']::text[],false,'{"seq":2,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"생각을 더 분명하게 나타낸 쪽은 어느 것인가요?","options":[{"t":"나뭇잎 하나도 예뻐요. 모이면 그늘이 돼요. 나도 친구들과 모이고 싶어요.","correct":true},{"t":"나뭇잎 하나도 예쁘고 모이면 그늘이 되고 그래서 나도 친구들과 모이고 싶고 그래요.","mis":"K1-2-u6-X07"},{"t":"나뭇잎.","mis":"K1-2-u6-X01"}],"explanation":["짧은 문장 세 개로 나누어 또렷해요.","한 문장에 다 이으면 뜻이 흐려져요.","짧게, 여러 개로."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#3','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',3,'mc','auto','시 「크레파스」가 들려주는 생각으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X09','K1-2-u6-X08']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「크레파스」가 들려주는 생각으로 알맞은 것은 어느 것인가요?","options":[{"t":"혼자서도 할 수 있는 일이 있고, 함께하면 더 큰 일도 할 수 있다","correct":true},{"t":"혼자서는 아무것도 할 수 없다","mis":"K1-2-u6-X09"},{"t":"크레파스는 빨간색이 가장 좋다","mis":"K1-2-u6-X08"}],"explanation":["사과 하나도, 무지개도 그렸어요.","혼자서 사과를 그렸으니 아무것도 못 하는 게 아니에요.","둘 다 그린 까닭을 생각해요."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#4','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',3,'mc','auto','시 「징검돌」에서 「친구들이 건너는 길이 되어요」가 뜻하는 것은 무엇인가요?',ARRAY['K1-2-u6-X08']::text[],true,'{"seq":4,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「징검돌」에서 「친구들이 건너는 길이 되어요」가 뜻하는 것은 무엇인가요?","options":[{"t":"여럿이 모이면 다른 사람을 도울 수 있다","correct":true},{"t":"돌이 길쭉하게 늘어난다","mis":"K1-2-u6-X08"},{"t":"냇물이 말라 버린다","mis":"K1-2-u6-X08"}],"explanation":["돌이 모여 친구들을 건너게 해 줘요.","돌이 늘어나거나 냇물이 마른다는 말은 없어요.","「길이 되어요」 속뜻을 생각해요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"},"variant_rule":{"alt":[{"stem":"시 「눈송이」에서 「하얀 눈사람이 생겨요」가 뜻하는 것은 무엇인가요?","options":[{"t":"작은 것도 모이면 큰 것이 될 수 있다","correct":true},{"t":"눈송이 하나는 쓸모가 없다","mis":"K1-2-u6-X09"},{"t":"눈사람은 한 송이로 만든다","mis":"K1-2-u6-X08"}],"explanation":["작은 눈송이가 쌓여 눈사람이 되었어요.","하나도 손등에 앉는 제 모습이 있어요.","모였을 때의 뜻을 생각해요."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#5','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',3,'ox','auto','「좋았어요.」라고만 쓰면 시를 읽고 무엇을 생각했는지 다른 사람이 알 수 있어요.',ARRAY['K1-2-u6-X07']::text[],true,'{"seq":5,"concept":"K1-2-u6-C3","difficulty":3,"kind":"ox","stem":"「좋았어요.」라고만 쓰면 시를 읽고 무엇을 생각했는지 다른 사람이 알 수 있어요.","answer":"X","reason_options":[{"t":"무엇이 어땠는지가 빠져 있으니까","correct":true},{"t":"짧을수록 잘 쓴 문장이니까","mis":"K1-2-u6-X07"}],"mis":"K1-2-u6-X01","explanation":["무엇이 어땠는지 넣어야 해요.","짧기만 하면 생각이 안 보여요.","「~이 ~해서 좋았어요」."],"variant_rule":{"alt":[{"stem":"시를 읽고 생각을 쓸 때 짧은 문장 여러 개로 나누어 쓰면 뜻이 더 분명해요.","answer":"O","reason_options":[{"t":"한 문장에 하나씩 담으면 또렷하니까","correct":true},{"t":"길게 이을수록 멋진 글이니까","mis":"K1-2-u6-X07"}],"explanation":["짧은 문장 여러 개가 또렷해요.","길게 이으면 뜻이 흐려져요.","한 문장에 생각 하나."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#6','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',3,'error','auto','여럿이 함께 하는 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#7','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',3,'mc','auto','시를 읽고 떠오른 생각과 그 까닭이 함께 있는 문장은 어느 것인가요?',ARRAY['K1-2-u6-X08','K1-2-u6-X01']::text[],false,'{"seq":7,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시를 읽고 떠오른 생각과 그 까닭이 함께 있는 문장은 어느 것인가요?","options":[{"t":"눈송이가 모여 눈사람이 된 것처럼, 우리 반도 힘을 모으면 큰일을 해낼 것 같아요.","correct":true},{"t":"마당에 하얀 눈사람이 생겨요.","mis":"K1-2-u6-X08"},{"t":"눈이 좋아요.","mis":"K1-2-u6-X01"}],"explanation":["생각과 「~처럼」 까닭이 함께 있어요.","첫째는 시를 옮겼고, 셋째는 느낌뿐이에요.","내 말로, 까닭과 함께."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#8','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',4,'sa','auto','시 「눈송이」를 읽고 빈칸에 「혼자」나 「함께」를 알맞게 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#9','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',4,'essay','teacher','「나뭇잎」을 읽고, 나는 혼자일 때와 함께일 때 어떻게 빛나고 싶은지 짧은 문장 두세 개로 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"「나뭇잎」을 읽고, 나는 혼자일 때와 함께일 때 어떻게 빛나고 싶은지 짧은 문장 두세 개로 쓰세요.","answer_guide":{"answer":"예: 혼자일 때는 책을 끝까지 읽고 싶어요. 친구들과 함께일 때는 모둠 그림을 멋지게 그리고 싶어요. — 혼자·함께 가운데 하나 이상과 내 다짐이 짧은 문장으로 있으면 맞아요.","scoring_points":["혼자일 때나 함께일 때의 모습이 있는가","내 생각을 내 말로 썼는가","짧은 문장 두세 개로 나누어 썼는가"]},"explanation":["정해진 답은 없어요.","짧은 문장 여러 개로.","「나도 ~하고 싶어요」."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L04_challenge#10','kor',1,2,'u6','L04','g1_2_kor_u6_L04_challenge','lesson_challenge','K1-2-u6-C3',4,'essay','teacher','시를 읽고 우리 반을 위해 내가 할 수 있는 일을, 무엇을 언제 할지 넣어 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"시를 읽고 우리 반을 위해 내가 할 수 있는 일을, 무엇을 언제 할지 넣어 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 아침에 교실에 오면 창문을 열어 맑은 바람이 들어오게 하겠어요. — 언제와 무엇을이 함께 있으면 맞아요.","scoring_points":["언제 할지 있는가","무엇을 할지 있는가","내가 실제로 할 수 있는 일인가"]},"explanation":["언제 + 무엇을.","「잘하겠어요」에서 그치지 않아요.","내가 할 수 있는 일로."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#1','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',1,'mc','auto','[솓]이라고 소리 나는, 밥을 짓는 그릇을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],true,'{"seq":1,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"[솓]이라고 소리 나는, 밥을 짓는 그릇을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"솥","correct":true},{"t":"솓","mis":"K1-2-u6-X10"},{"t":"솟","mis":"K1-2-u6-X10"}],"explanation":["소리는 [솓]이지만 글자는 「솥」이에요.","소리 나는 대로 쓰면 다른 글자가 돼요.","받침 글자는 그대로."],"variant_rule":{"alt":[{"stem":"[겯]이라고 소리 나는, 바로 옆을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"곁","correct":true},{"t":"겯","mis":"K1-2-u6-X10"},{"t":"겻","mis":"K1-2-u6-X10"}],"explanation":["소리는 [겯]이지만 글자는 「곁」이에요.","소리 나는 대로 쓰면 다른 글자가 돼요.","받침 글자는 그대로."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#2','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',1,'mc','auto','소리와 글자가 다른 낱말은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],true,'{"seq":2,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"소리와 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"엿","correct":true},{"t":"사과","mis":"K1-2-u6-X10"},{"t":"오리","mis":"K1-2-u6-X10"}],"explanation":["「엿」은 [엳]으로 소리 나요.","사과·오리는 쓴 대로 소리 나요.","소리 내어 읽고 글자와 견주어요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 소리와 글자가 다른 낱말은 어느 것인가요?","options":[{"t":"늪","correct":true},{"t":"나무","mis":"K1-2-u6-X10"},{"t":"기차","mis":"K1-2-u6-X10"}],"explanation":["「늪」은 [늡]으로 소리 나요.","나무·기차는 쓴 대로 소리 나요.","받침을 살펴요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#3','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',1,'mc','auto','소리 나는 대로만 쓰면 어떤 일이 생기나요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":3,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"소리 나는 대로만 쓰면 어떤 일이 생기나요?","options":[{"t":"읽는 사람이 무슨 낱말인지 알기 어렵다","correct":true},{"t":"글자 수가 늘어난다","mis":"K1-2-u6-X10"},{"t":"뜻이 더 분명해진다","mis":"K1-2-u6-X10"}],"explanation":["「밥솓」이라 쓰면 무슨 뜻인지 헷갈려요.","글자 수나 뜻이 좋아지지 않아요.","글자는 뜻을 전하려고 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#4','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',1,'blank','auto','빈칸에 알맞은 낱말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#5','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',2,'match','auto','낱말과 소리를 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"솥","r":"[솓]"},{"l":"곁","r":"[겯]"},{"l":"늪","r":"[늡]"}],"mis":"K1-2-u6-X10","explanation":["솥은 [솓], 곁은 [겯]으로 소리 나요.","늪은 [늡]으로 소리 나요.","글자와 소리가 달라요."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"엿","r":"[엳]"},{"l":"붓","r":"[붇]"},{"l":"볕","r":"[볃]"}],"explanation":["엿은 [엳], 붓은 [붇]으로 소리 나요.","볕은 [볃]으로 소리 나요.","글자와 소리가 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#6','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',2,'mc','auto','[곧]이라고 소리 나는 낱말이 둘 있어요. 「우리가 사는 (  )」에 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X11']::text[],true,'{"seq":6,"concept":"K1-2-u6-C4","difficulty":2,"kind":"mc","stem":"[곧]이라고 소리 나는 낱말이 둘 있어요. 「우리가 사는 (  )」에 알맞은 것은 어느 것인가요?","options":[{"t":"곳","correct":true},{"t":"곧","mis":"K1-2-u6-X11"},{"t":"곶","mis":"K1-2-u6-X11"}],"explanation":["자리·장소는 「곳」이에요.","「곧」은 조금 뒤에라는 뜻이에요.","소리는 같아도 뜻이 달라요."],"variant_rule":{"alt":[{"stem":"[곧]이라고 소리 나는 낱말이 둘 있어요. 「(  ) 수업이 시작돼요.」에 알맞은 것은 어느 것인가요?","options":[{"t":"곧","correct":true},{"t":"곳","mis":"K1-2-u6-X11"},{"t":"곶","mis":"K1-2-u6-X11"}],"explanation":["조금 뒤에는 「곧」이에요.","「곳」은 장소라는 뜻이에요.","소리는 같아도 뜻이 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#7','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',2,'ox','auto','「짓다」와 「짖다」는 소리가 같으니 뜻도 같아요.',ARRAY['K1-2-u6-X11']::text[],true,'{"seq":7,"concept":"K1-2-u6-C4","difficulty":2,"kind":"ox","stem":"「짓다」와 「짖다」는 소리가 같으니 뜻도 같아요.","answer":"X","reason_options":[{"t":"소리는 같아도 글자가 달라 뜻이 다르니까","correct":true},{"t":"소리가 같으면 같은 낱말이니까","mis":"K1-2-u6-X11"}],"mis":"K1-2-u6-X11","explanation":["집을 짓다, 개가 짖다 — 뜻이 달라요.","소리만 같아요.","글자를 보고 뜻을 가려요."],"variant_rule":{"alt":[{"stem":"「곳」과 「곧」은 소리는 같지만 뜻이 달라요.","answer":"O","reason_options":[{"t":"글자가 다르면 뜻도 다르니까","correct":true},{"t":"소리가 같으면 뜻도 같으니까","mis":"K1-2-u6-X11"}],"explanation":["곳은 장소, 곧은 조금 뒤에.","소리만 같아요.","글자를 보고 뜻을 가려요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#8','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',2,'mc','auto','개가 멍멍 소리를 내는 것을 바르게 쓴 문장은 어느 것인가요?',ARRAY['K1-2-u6-X11','K1-2-u6-X10']::text[],true,'{"seq":8,"concept":"K1-2-u6-C4","difficulty":2,"kind":"mc","stem":"개가 멍멍 소리를 내는 것을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"개가 짖어요.","correct":true},{"t":"개가 지어요.","mis":"K1-2-u6-X11"},{"t":"개가 짇어요.","mis":"K1-2-u6-X10"}],"explanation":["개가 소리 내는 것은 「짖다」예요.","「지어요」는 집을 지을 때 써요.","받침 ㅈ."],"variant_rule":{"alt":[{"stem":"집을 만드는 것을 바르게 쓴 문장은 어느 것인가요?","options":[{"t":"목수가 집을 지어요.","correct":true},{"t":"목수가 집을 짖어요.","mis":"K1-2-u6-X11"},{"t":"목수가 집을 짇어요.","mis":"K1-2-u6-X10"}],"explanation":["집을 만드는 것은 「짓다」 — 「지어요」예요.","「짖어요」는 개가 소리 낼 때 써요.","뜻을 먼저 생각해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_basic#9','kor',1,2,'u6','L06','g1_2_kor_u6_L06_basic','lesson_basic','K1-2-u6-C4',2,'mc','auto','「붓」을 소리 내어 읽으면 어떻게 소리 나나요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"mc","stem":"「붓」을 소리 내어 읽으면 어떻게 소리 나나요?","options":[{"t":"[붇]","correct":true},{"t":"[붓]","mis":"K1-2-u6-X10"},{"t":"[부]","mis":"K1-2-u6-X10"}],"explanation":["「붓」은 [붇]으로 소리 나요.","받침 소리가 사라지지도, ㅅ 소리가 나지도 않아요.","소리 내어 읽어 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
