INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#7','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',3,'ox','auto','받침 소리가 달라져도 글자는 처음 그대로 써요.',ARRAY['K1-2-u6-X10']::text[],true,'{"seq":7,"concept":"K1-2-u6-C4","difficulty":3,"kind":"ox","stem":"받침 소리가 달라져도 글자는 처음 그대로 써요.","answer":"O","reason_options":[{"t":"글자를 그대로 써야 뜻을 알아볼 수 있으니까","correct":true},{"t":"들리는 소리대로 써야 맞는 글자니까","mis":"K1-2-u6-X10"}],"mis":"K1-2-u6-X10","explanation":["솥을 [솓]으로 읽어도 글자는 솥.","소리대로 쓰면 뜻을 알기 어려워요.","글자는 그대로."],"variant_rule":{"alt":[{"stem":"「곁」은 [겯]으로 소리 나니까 「겯」이라고 써야 해요.","answer":"X","reason_options":[{"t":"소리는 [겯]이어도 글자는 「곁」이니까","correct":true},{"t":"소리 나는 대로 쓰는 것이 맞으니까","mis":"K1-2-u6-X10"}],"explanation":["글자는 「곁」이에요.","소리대로 쓰면 다른 글자가 돼요.","글자는 그대로."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#8','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',4,'sa','auto','[늡]이라고 소리 나는, 물이 고여 질척한 땅을 뜻하는 낱말을 바르게 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u6-C4","difficulty":4,"kind":"sa","stem":"[늡]이라고 소리 나는, 물이 고여 질척한 땅을 뜻하는 낱말을 바르게 쓰세요.","answer":["늪"],"explanation":["글자는 「늪」이에요.","받침 ㅍ이 [ㅂ]처럼 소리 나요.","소리대로 쓰지 않아요."],"variant_rule":{"alt":[{"stem":"[솓]이라고 소리 나는, 밥을 짓는 그릇을 뜻하는 낱말을 바르게 쓰세요.","answer":["솥"],"explanation":["글자는 「솥」이에요.","받침 ㅌ이 [ㄷ]처럼 소리 나요.","소리대로 쓰지 않아요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#9','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',4,'sa','auto','[볃]으로 소리 나는 낱말을 바르게 써서 빈칸을 채우세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L06_challenge#10','kor',1,2,'u6','L06','g1_2_kor_u6_L06_challenge','lesson_challenge','K1-2-u6-C4',4,'essay','teacher','교실이나 집에서 소리와 글자가 다른 낱말을 하나 찾아, 글자와 소리를 쓰고 그 낱말을 넣은 문장을 하나 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C4","difficulty":4,"kind":"essay","stem":"교실이나 집에서 소리와 글자가 다른 낱말을 하나 찾아, 글자와 소리를 쓰고 그 낱말을 넣은 문장을 하나 쓰세요.","answer_guide":{"answer":"예: 글자 「솥」, 소리 [솓]. 문장: 밥솥에서 하얀 김이 나요. — 소리와 글자가 다른 낱말을 바르게 쓰고 문장에 알맞게 넣었으면 맞아요.","scoring_points":["소리와 글자가 다른 낱말인가","글자를 바르게 썼는가","낱말을 넣은 문장이 뜻에 맞는가"]},"explanation":["받침이 다르게 소리 나는 낱말을 찾아요.","글자는 바르게, 소리는 [ ] 안에.","문장에 넣어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#1','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','문장을 자연스럽게 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":1,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"문장을 자연스럽게 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"뜻이 이어지는 말끼리 묶어 읽는다","correct":true},{"t":"한 글자씩 끊어 읽는다","mis":"K1-2-u6-X13"},{"t":"처음부터 끝까지 쉬지 않고 읽는다","mis":"K1-2-u6-X14"}],"explanation":["덩어리로 묶으면 뜻이 잘 통해요.","끊거나 붙이면 알아듣기 어려워요.","뜻이 이어지는 말끼리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#2','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],true,'{"seq":2,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"비누로 ∨ 손을 씻어 주세요.","correct":true},{"t":"비누로손을씻어주세요.","mis":"K1-2-u6-X14"},{"t":"비 ∨ 누로 손을 씻 ∨ 어 주세요.","mis":"K1-2-u6-X13"}],"explanation":["뜻이 이어지는 덩어리에서 쉬었어요.","붙여 읽거나 낱말 가운데에서 쉬면 뜻이 흐려져요.","낱말은 한 덩어리."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. (∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"다 읽은 책은 ∨ 반납함에 넣어 주세요.","correct":true},{"t":"다읽은책은반납함에넣어주세요.","mis":"K1-2-u6-X14"},{"t":"다 읽은 책은 반 ∨ 납함에 넣어 주세요.","mis":"K1-2-u6-X13"}],"explanation":["뜻이 이어지는 덩어리에서 쉬었어요.","붙여 읽거나 낱말 가운데에서 쉬면 뜻이 흐려져요.","낱말은 한 덩어리."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#3','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','쉬지 않고 붙여 읽으면 어떻게 되나요?',ARRAY['K1-2-u6-X14']::text[],false,'{"seq":3,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"쉬지 않고 붙여 읽으면 어떻게 되나요?","options":[{"t":"듣는 사람이 뜻을 잡기 어렵다","correct":true},{"t":"더 또박또박 들린다","mis":"K1-2-u6-X14"},{"t":"뜻이 더 잘 통한다","mis":"K1-2-u6-X14"}],"explanation":["말이 한데 엉겨 무슨 뜻인지 놓쳐요.","붙여 읽어서 또박또박해지지 않아요.","덩어리마다 숨을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#4','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',1,'mc','auto','낱말 가운데에서 쉬면 어떻게 되나요?',ARRAY['K1-2-u6-X13']::text[],false,'{"seq":4,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"낱말 가운데에서 쉬면 어떻게 되나요?","options":[{"t":"낱말이 잘려 뜻이 끊어진다","correct":true},{"t":"글자가 더 예쁘게 들린다","mis":"K1-2-u6-X13"},{"t":"아무 차이가 없다","mis":"K1-2-u6-X13"}],"explanation":["「비 ∨ 누」처럼 자르면 무슨 낱말인지 몰라요.","차이가 아주 커요.","낱말은 통째로 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#5','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'ox','auto','뜻이 잘 통한다면 쉬어 읽는 곳은 사람마다 다를 수 있어요.',ARRAY['K1-2-u6-X15']::text[],true,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"뜻이 잘 통한다면 쉬어 읽는 곳은 사람마다 다를 수 있어요.","answer":"O","reason_options":[{"t":"뜻이 이어지는 덩어리는 여러 가지로 묶을 수 있으니까","correct":true},{"t":"쉬는 곳은 문장마다 딱 한 군데로 정해져 있으니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["쉬는 곳은 여럿일 수 있어요.","뜻이 통하는지가 기준이에요.","친구와 달라도 괜찮아요."],"variant_rule":{"alt":[{"stem":"띄어 쓴 곳에서는 모두 쉬어 읽어야 해요.","answer":"X","reason_options":[{"t":"띄어 쓴 곳마다 쉬면 오히려 뚝뚝 끊겨 들리니까","correct":true},{"t":"띄어 쓴 곳이 바로 쉬는 곳이니까","mis":"K1-2-u6-X15"}],"explanation":["띄어 쓴 곳마다 쉬지는 않아요.","뜻이 이어지는 덩어리로 묶어요.","쉬는 곳은 뜻으로 정해요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#6','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 뜻이 끊어지게 쉰 것은 어느 것인가요?',ARRAY['K1-2-u6-X15']::text[],true,'{"seq":6,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 뜻이 끊어지게 쉰 것은 어느 것인가요?","options":[{"t":"팔꿈 ∨ 치로 입을 가려 주세요.","correct":true},{"t":"기침이 나면 ∨ 팔꿈치로 입을 가려 주세요.","mis":"K1-2-u6-X15"},{"t":"팔꿈치로 ∨ 입을 가려 주세요.","mis":"K1-2-u6-X15"}],"explanation":["「팔꿈치」 가운데에서 쉬었어요.","나머지 둘은 뜻이 통하게 쉬었어요 — 쉬는 곳이 달라도 괜찮아요.","낱말 가운데를 살펴요."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. (∨ 는 쉬어 읽는 곳이에요.) 뜻이 끊어지게 쉰 것은 어느 것인가요?","options":[{"t":"작은 목소 ∨ 리로 이야기해요.","correct":true},{"t":"도서관에서는 ∨ 작은 목소리로 이야기해요.","mis":"K1-2-u6-X15"},{"t":"작은 목소리로 ∨ 이야기해요.","mis":"K1-2-u6-X15"}],"explanation":["「목소리」 가운데에서 쉬었어요.","나머지 둘은 뜻이 통하게 쉬었어요.","낱말 가운데를 살펴요."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#7','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C6',2,'match','auto','「보건 선생님의 부탁」에서 부탁과 그 까닭을 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「보건 선생님의 부탁」에서 부탁과 그 까닭을 선으로 이어 보세요.","pairs":[{"l":"비누로 손 씻기","r":"손에 묻은 더러운 것을 없애려고"},{"l":"팔꿈치로 입 가리기","r":"침이 다른 사람에게 튀지 않게"},{"l":"다치면 바로 알리기","r":"빨리 치료를 받으려고"}],"mis":"K1-2-u6-X17","explanation":["부탁마다 까닭이 있어요.","까닭을 알면 뜻을 살려 읽을 수 있어요.","부탁 하나씩 떠올려요."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#8','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「책장은 찢어지지 않게 살살 넘겨 주세요.」를 뜻이 잘 통하게 쉰 것은 어느 것인가요?',ARRAY['K1-2-u6-X15','K1-2-u6-X13']::text[],false,'{"seq":8,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「책장은 찢어지지 않게 살살 넘겨 주세요.」를 뜻이 잘 통하게 쉰 것은 어느 것인가요?","options":[{"t":"책장은 ∨ 찢어지지 않게 ∨ 살살 넘겨 주세요.","correct":true},{"t":"책장은 ∨ 찢어지지 ∨ 않게 ∨ 살살 ∨ 넘겨 ∨ 주세요.","mis":"K1-2-u6-X15"},{"t":"책장은 찢어지지 않게 살 ∨ 살 넘겨 주세요.","mis":"K1-2-u6-X13"}],"explanation":["뜻이 이어지는 덩어리 둘·셋으로 묶었어요.","띄어 쓴 곳마다 쉬면 뚝뚝 끊기고, 「살살」을 자르면 안 돼요.","덩어리로."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_basic#9','kor',1,2,'u6','L08','g1_2_kor_u6_L08_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','두 친구의 읽기에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"두 친구의 읽기에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"둘 다 뜻이 통하게 읽었으니 괜찮다","correct":true},{"t":"지안이만 맞고 서진이는 틀렸다","mis":"K1-2-u6-X15"},{"t":"쉬는 곳이 서로 달라서 둘 다 틀렸다","mis":"K1-2-u6-X15"}],"explanation":["쉬는 곳이 달라도 뜻이 잘 통해요.","쉬는 곳은 여럿일 수 있어요.","뜻이 통하는지가 기준."],"asset":{"type":"speech","turns":[{"who":"지안","text":"도서관에서는 ∨ 작은 목소리로 이야기해요."},{"who":"서진","text":"도서관에서는 작은 목소리로 ∨ 이야기해요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
