INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#1','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":1,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"넘어져 다치면 ∨ 바로 선생님께 알려 주세요.","correct":true},{"t":"넘어져다치면바로선생님께알려주세요.","mis":"K1-2-u6-X14"},{"t":"넘어져 다치면 바로 선생 ∨ 님께 알려 주세요.","mis":"K1-2-u6-X13"}],"explanation":["뜻이 이어지는 덩어리에서 쉬었어요.","붙이거나 「선생님」을 자르면 뜻이 흐려져요.","낱말은 한 덩어리."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#2','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',2,'ox','auto','친구와 쉬는 곳이 다르면 둘 가운데 하나는 틀린 거예요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":2,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"친구와 쉬는 곳이 다르면 둘 가운데 하나는 틀린 거예요.","answer":"X","reason_options":[{"t":"뜻이 통하면 쉬는 곳은 여럿일 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["둘 다 맞을 수 있어요.","뜻이 통하는지 서로 들어 봐요.","다르다고 틀린 것이 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
