INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#4','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 세 읽기 가운데 뜻이 가장 잘 통하는 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],true,'{"seq":4,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 세 읽기 가운데 뜻이 가장 잘 통하는 것은 어느 것인가요?","options":[{"t":"기침이 나면 ∨ 팔꿈치로 입을 가려 주세요.","correct":true},{"t":"기침이 나면 팔 ∨ 꿈치로 입을 가려 주세요.","mis":"K1-2-u6-X13"},{"t":"기침이나면팔꿈치로입을가려주세요.","mis":"K1-2-u6-X14"}],"explanation":["뜻이 이어지는 두 덩어리로 읽었어요.","낱말을 자르거나 붙이면 알아듣기 어려워요.","덩어리로."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"},"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. (∨ 는 쉬어 읽는 곳이에요.) 세 읽기 가운데 뜻이 가장 잘 통하는 것은 어느 것인가요?","options":[{"t":"책을 아끼면 ∨ 다음 친구도 즐겁게 읽을 수 있어요.","correct":true},{"t":"책을 아끼면 다음 친구도 즐 ∨ 겁게 읽을 수 있어요.","mis":"K1-2-u6-X13"},{"t":"책을아끼면다음친구도즐겁게읽을수있어요.","mis":"K1-2-u6-X14"}],"explanation":["뜻이 이어지는 두 덩어리로 읽었어요.","낱말을 자르거나 붙이면 알아듣기 어려워요.","덩어리로."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#5','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'mc','auto','띄어 읽기를 하는 까닭은 무엇인가요?',ARRAY['K1-2-u6-X19','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":3,"kind":"mc","stem":"띄어 읽기를 하는 까닭은 무엇인가요?","options":[{"t":"듣는 사람이 뜻을 알아듣기 쉽게 하려고","correct":true},{"t":"누가 더 빨리 읽나 겨루려고","mis":"K1-2-u6-X19"},{"t":"숨이 찰 때 아무 데서나 쉬려고","mis":"K1-2-u6-X13"}],"explanation":["띄어 읽기는 듣는 사람을 위한 거예요.","겨루기나 아무 데서나 쉬기가 아니에요.","뜻이 통하게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#6','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','「사서 선생님의 부탁」에서 책장을 살살 넘기라고 한 까닭은 무엇인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"「사서 선생님의 부탁」에서 책장을 살살 넘기라고 한 까닭은 무엇인가요?","options":[{"t":"책장이 찢어지지 않게 하려고","correct":true},{"t":"책을 빨리 읽으려고","mis":"K1-2-u6-X17"},{"t":"소리를 크게 내려고","mis":"K1-2-u6-X17"}],"explanation":["「찢어지지 않게」라고 했어요.","빨리 읽거나 소리를 내라는 말은 없어요.","뜻을 알면 읽기도 쉬워요."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#7','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',3,'match','auto','읽는 모습과 그 결과를 선으로 이어 보세요.','{}'::text[],false,'{"seq":7,"concept":"K1-2-u6-C5","difficulty":3,"kind":"match","stem":"읽는 모습과 그 결과를 선으로 이어 보세요.","pairs":[{"l":"쉬지 않고 붙여 읽기","r":"듣는 사람이 뜻을 잡기 어려워요"},{"l":"글자마다 끊어 읽기","r":"뚝뚝 끊겨 뜻이 흩어져요"},{"l":"덩어리로 묶어 읽기","r":"뜻이 잘 통해요"}],"mis":"K1-2-u6-X13","explanation":["붙이면 엉기고, 끊으면 흩어져요.","덩어리로 묶어야 잘 통해요.","읽는 모습을 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#8','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'sa','auto','「책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요.」를 뜻이 통하게 두 덩어리로 나누어 읽으려고 해요. 첫 덩어리의 마지막 낱말을 하나 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"K1-2-u6-C5","difficulty":4,"kind":"sa","stem":"「책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요.」를 뜻이 통하게 두 덩어리로 나누어 읽으려고 해요. 첫 덩어리의 마지막 낱말을 하나 쓰세요.","answer":["아끼면","친구도"],"explanation":["「책을 아끼면 ∨」이나 「다음 친구도 ∨」 모두 뜻이 통해요.","낱말 가운데에서 나누지 않아요.","쉬는 곳은 여럿일 수 있어요."],"asset":{"type":"passage","lines":["도서관에서는 작은 목소리로 이야기해요.","다 읽은 책은 반납함에 넣어 주세요.","책장은 찢어지지 않게 살살 넘겨 주세요.","책을 아끼면 다음 친구도 즐겁게 읽을 수 있어요."],"title":"「사서 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#9','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'essay','teacher','「보건 선생님의 부탁」에서 한 문장을 골라 쉬어 읽을 곳에 ∨ 표를 하여 쓰고, 왜 거기에서 쉬었는지 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"「보건 선생님의 부탁」에서 한 문장을 골라 쉬어 읽을 곳에 ∨ 표를 하여 쓰고, 왜 거기에서 쉬었는지 쓰세요.","answer_guide":{"answer":"예: 놀이 시간이 끝나면 ∨ 비누로 손을 씻어 주세요. 「언제」에 해당하는 말이 끝나는 곳이라서 쉬었어요. — 낱말 가운데가 아닌 곳에서 쉬고 까닭이 있으면 맞아요(쉬는 곳은 여럿일 수 있어요).","scoring_points":["∨ 표가 낱말 가운데가 아닌가","뜻이 이어지는 덩어리로 나누었는가","쉰 까닭을 썼는가"]},"explanation":["정해진 한 곳은 없어요.","낱말 가운데만 피해요.","왜 거기인지 써요."],"asset":{"type":"passage","lines":["놀이 시간이 끝나면 비누로 손을 씻어 주세요.","기침이 나면 팔꿈치로 입을 가려 주세요.","넘어져 다치면 바로 선생님께 알려 주세요.","모두 건강하게 지내면 좋겠어요."],"title":"「보건 선생님의 부탁」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L08_challenge#10','kor',1,2,'u6','L08','g1_2_kor_u6_L08_challenge','lesson_challenge','K1-2-u6-C5',4,'essay','teacher','시온이처럼 읽은 친구에게, 어떻게 읽으면 좋을지 알려 주는 말을 친절하게 두 문장으로 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C5","difficulty":4,"kind":"essay","stem":"시온이처럼 읽은 친구에게, 어떻게 읽으면 좋을지 알려 주는 말을 친절하게 두 문장으로 쓰세요.","answer_guide":{"answer":"예: 글자마다 끊으면 무슨 말인지 알기 어려워. 「도서관에서는」까지 한 번에 읽고 조금 쉬어 봐. — 고칠 점과 방법을 나무라지 않고 알려 주면 맞아요.","scoring_points":["무엇이 문제인지 말했는가","덩어리로 묶어 읽는 방법을 알려 주었는가","친구가 기분 상하지 않게 말했는가"]},"explanation":["글자마다 끊은 것이 문제예요.","덩어리로 묶는 방법을 알려 줘요.","친절하게."],"asset":{"type":"speech","turns":[{"who":"시온","text":"도 ∨ 서 ∨ 관 ∨ 에 ∨ 서 ∨ 는 ∨ 작 ∨ 은 ∨ 목 ∨ 소 ∨ 리 ∨ 로"},{"who":"해린","text":"(고개를 갸웃하며) 무슨 말인지 잘 모르겠어."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#1','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','「다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],true,'{"seq":1,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"다람쥐가","correct":true},{"t":"도토리를","mis":"K1-2-u6-X16"},{"t":"겨울을","mis":"K1-2-u6-X16"}],"explanation":["묻은 것은 다람쥐예요.","도토리는 무엇을, 겨울은 때예요.","「누가 묻었나요?」 물어요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"},"variant_rule":{"alt":[{"stem":"「엄마 펭귄이 먼저 물속으로 뛰어들었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"엄마 펭귄이","correct":true},{"t":"물속으로","mis":"K1-2-u6-X16"},{"t":"먼저","mis":"K1-2-u6-X16"}],"explanation":["뛰어든 것은 엄마 펭귄이에요.","물속으로는 어디로, 먼저는 언제예요.","「누가 뛰어들었나요?」 물어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#2','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','문장과 문장 사이에서는 어떻게 읽나요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":2,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"문장과 문장 사이에서는 어떻게 읽나요?","options":[{"t":"숨을 한 번 고르고 다음 문장을 읽는다","correct":true},{"t":"앞 문장 끝에 붙여 곧장 읽는다","mis":"K1-2-u6-X14"},{"t":"한 글자씩 끊어 읽는다","mis":"K1-2-u6-X13"}],"explanation":["문장 사이에서는 조금 더 쉬어요.","붙이거나 끊으면 뜻이 흐려져요.","마침표에서 숨 고르기."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#3','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','다람쥐가 도토리를 묻은 때는 언제인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":3,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"다람쥐가 도토리를 묻은 때는 언제인가요?","options":[{"t":"겨울을 앞두고","correct":true},{"t":"봄이 오고 나서","mis":"K1-2-u6-X17"},{"t":"눈이 녹은 뒤","mis":"K1-2-u6-X17"}],"explanation":["첫째 줄에 「겨울을 앞두고」라고 했어요.","봄과 눈 녹음은 싹이 돋을 때예요.","첫째 줄을 봐요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#4','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',1,'mc','auto','아기 펭귄이 처음에 발만 담갔다가 뺀 까닭은 무엇인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":4,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"아기 펭귄이 처음에 발만 담갔다가 뺀 까닭은 무엇인가요?","options":[{"t":"물이 차가워서","correct":true},{"t":"엄마가 부르셔서","mis":"K1-2-u6-X17"},{"t":"물이 너무 따뜻해서","mis":"K1-2-u6-X17"}],"explanation":["「물이 차가워서」라고 했어요.","부르거나 따뜻하다는 말은 없어요.","둘째 줄을 봐요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#5','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.」를 뜻이 잘 통하게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":5,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.」를 뜻이 잘 통하게 읽은 것은 어느 것인가요?","options":[{"t":"아기 펭귄도 ∨ 용기를 내어 첨벙 뛰어들었어요.","correct":true},{"t":"아기 ∨ 펭귄도 용기를 내 ∨ 어 첨벙 뛰어들었어요.","mis":"K1-2-u6-X13"},{"t":"아기펭귄도용기를내어첨벙뛰어들었어요.","mis":"K1-2-u6-X14"}],"explanation":["「누가」(아기 펭귄도) 뒤에서 조금 쉬었어요.","낱말을 자르거나 붙이면 뜻이 흐려져요.","누가 뒤에서 쉬어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#6','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'match','auto','「다람쥐의 도토리」에서 차례와 있었던 일을 선으로 이어 보세요.','{}'::text[],true,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「다람쥐의 도토리」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"도토리를 땅에 묻었어요"},{"l":"가운데","r":"묻은 곳을 잊어버렸어요"},{"l":"끝","r":"그 자리에서 싹이 돋았어요"}],"mis":"K1-2-u6-X17","explanation":["묻고 → 잊고 → 싹이 돋았어요.","「그런데」, 「봄이 왔어요」가 차례를 알려 줘요.","줄 차례를 따라가요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"},"variant_rule":{"alt":[{"stem":"「아기 펭귄의 첫 헤엄」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"발만 담갔다가 뺐어요"},{"l":"가운데","r":"엄마 펭귄이 먼저 뛰어들었어요"},{"l":"끝","r":"용기를 내어 뛰어들어 헤엄쳤어요"}],"explanation":["망설임 → 엄마가 먼저 → 아기도 뛰어듦.","「먼저」, 「도」가 차례를 알려 줘요.","줄 차례를 따라가요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#7','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'ox','auto','「누가·무엇이」에 해당하는 말이 길면 그 말 안에서 한 번 더 쉬어 읽어도 돼요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":7,"concept":"K1-2-u6-C6","difficulty":2,"kind":"ox","stem":"「누가·무엇이」에 해당하는 말이 길면 그 말 안에서 한 번 더 쉬어 읽어도 돼요.","answer":"O","reason_options":[{"t":"긴 말을 한 번에 읽으면 숨이 차고 뜻이 흐려지니까","correct":true},{"t":"쉬는 곳은 한 문장에 한 번만 있으니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X16","explanation":["길면 한 번 더 쉬어요.","낱말 가운데만 아니면 돼요.","듣는 사람이 알아듣게."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#8','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','다람쥐가 싹을 보고 눈이 동그래진 까닭으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":8,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"다람쥐가 싹을 보고 눈이 동그래진 까닭으로 알맞은 것은 어느 것인가요?","options":[{"t":"잊어버린 도토리가 싹으로 자라서 놀라서","correct":true},{"t":"도토리를 다 먹어서","mis":"K1-2-u6-X17"},{"t":"눈이 아파서","mis":"K1-2-u6-X17"}],"explanation":["묻은 곳을 잊었는데 그 자리에서 싹이 났어요.","다 먹었다거나 눈이 아프다는 말은 없어요.","앞의 일과 이어 생각해요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#9','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',2,'mc','auto','이야기를 소리 내어 읽을 때 쉬는 곳을 알맞게 정하려면 무엇을 생각해야 하나요?',ARRAY['K1-2-u6-X13','K1-2-u6-X19']::text[],false,'{"seq":9,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"이야기를 소리 내어 읽을 때 쉬는 곳을 알맞게 정하려면 무엇을 생각해야 하나요?","options":[{"t":"문장의 뜻과 이야기 내용","correct":true},{"t":"글자 수를 세어 똑같이 나누기","mis":"K1-2-u6-X13"},{"t":"친구보다 빨리 끝내기","mis":"K1-2-u6-X19"}],"explanation":["뜻을 알면 쉬는 곳이 보여요.","글자 수나 빠르기는 기준이 아니에요.","내용을 떠올리며 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_basic#10','kor',1,2,'u6','L10','g1_2_kor_u6_L10_basic','lesson_basic','K1-2-u6-C6',3,'error','auto','「아기 펭귄의 첫 헤엄」을 차례대로 말했어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#1','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',2,'mc','auto','「물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":1,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"「물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"아기 펭귄은","correct":true},{"t":"물속에서","mis":"K1-2-u6-X16"},{"t":"새처럼","mis":"K1-2-u6-X16"}],"explanation":["헤엄친 것은 아기 펭귄이에요.","「누가」가 문장 맨 앞에 있지 않을 때도 있어요.","「누가 헤엄쳤나요?」 물어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#2','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',2,'mc','auto','아기 펭귄의 마음은 어떻게 바뀌었나요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":2,"concept":"K1-2-u6-C6","difficulty":2,"kind":"mc","stem":"아기 펭귄의 마음은 어떻게 바뀌었나요?","options":[{"t":"겁이 났다가 용기를 냈다","correct":true},{"t":"신났다가 화가 났다","mis":"K1-2-u6-X17"},{"t":"처음부터 끝까지 무서웠다","mis":"K1-2-u6-X17"}],"explanation":["발만 담갔다가 → 용기를 내어 뛰어들었어요.","화나거나 끝까지 무섭다는 말은 없어요.","처음과 끝을 견주어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#3','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','첫째 줄과 둘째 줄을 이어 읽을 때 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":3,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"첫째 줄과 둘째 줄을 이어 읽을 때 알맞은 것은 어느 것인가요?","options":[{"t":"첫 문장이 끝나면 조금 더 쉬고 둘째 문장을 읽는다","correct":true},{"t":"두 문장을 한 문장처럼 쉬지 않고 이어 읽는다","mis":"K1-2-u6-X14"},{"t":"「그런 ∨ 데」처럼 낱말 가운데에서 쉰다","mis":"K1-2-u6-X13"}],"explanation":["문장 사이에서는 조금 더 쉬어요.","붙이거나 낱말을 자르면 안 돼요.","마침표에서 숨 고르기."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#4','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','「누가」에 해당하는 말이 가장 긴 문장은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":4,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"「누가」에 해당하는 말이 가장 긴 문장은 어느 것인가요?","options":[{"t":"우리 반에서 키가 가장 큰 친구가 공을 찼어요.","correct":true},{"t":"지안이가 웃어요.","mis":"K1-2-u6-X16"},{"t":"새가 날아요.","mis":"K1-2-u6-X16"}],"explanation":["「우리 반에서 키가 가장 큰 친구가」가 모두 누가예요.","지안이가, 새가는 짧아요.","길면 그 안에서 한 번 더 쉬어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#5','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「우리 반에서 키가 가장 큰 친구가 공을 찼어요.」를 뜻이 잘 통하게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「우리 반에서 키가 가장 큰 친구가 공을 찼어요.」를 뜻이 잘 통하게 읽은 것은 어느 것인가요?","options":[{"t":"우리 반에서 ∨ 키가 가장 큰 친구가 ∨ 공을 찼어요.","correct":true},{"t":"우리반에서키가가장큰친구가공을찼어요.","mis":"K1-2-u6-X14"},{"t":"우리 반 ∨ 에서 키가 가 ∨ 장 큰 친구가 공을 찼어요.","mis":"K1-2-u6-X13"}],"explanation":["긴 「누가」 안에서 한 번, 그 뒤에서 한 번 쉬었어요.","붙이거나 낱말을 자르면 안 돼요.","길면 한 번 더."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#6','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'error','auto','쉬어 읽기 원칙을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#7','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',3,'mc','auto','엄마 펭귄이 먼저 물속으로 뛰어든 까닭으로 짐작할 수 있는 것은 어느 것인가요?',ARRAY['K1-2-u6-X17']::text[],true,'{"seq":7,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"엄마 펭귄이 먼저 물속으로 뛰어든 까닭으로 짐작할 수 있는 것은 어느 것인가요?","options":[{"t":"아기 펭귄에게 괜찮다는 것을 보여 주려고","correct":true},{"t":"혼자 먼저 놀고 싶어서","mis":"K1-2-u6-X17"},{"t":"물이 차가운지 몰라서","mis":"K1-2-u6-X17"}],"explanation":["먼저 뛰어든 뒤 아기도 용기를 냈어요.","혼자 놀았다거나 몰랐다는 말은 없어요.","앞뒤 일을 이어 짐작해요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"},"variant_rule":{"alt":[{"stem":"다람쥐가 묻은 곳을 잊어버려서 생긴 일은 무엇인가요?","options":[{"t":"그 자리에서 도토리 싹이 돋았다","correct":true},{"t":"다람쥐가 도토리를 다 먹었다","mis":"K1-2-u6-X17"},{"t":"눈이 녹지 않았다","mis":"K1-2-u6-X17"}],"explanation":["잊고 남은 도토리가 봄에 싹이 되었어요.","다 먹었다거나 눈이 안 녹았다는 말은 없어요.","앞뒤 일을 이어 생각해요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#8','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'sa','auto','「다람쥐는 싹을 보고 눈이 동그래졌어요.」에서 「누가」에 해당하는 말을 쓰세요.','{}'::text[],true,'{"seq":8,"concept":"K1-2-u6-C6","difficulty":4,"kind":"sa","stem":"「다람쥐는 싹을 보고 눈이 동그래졌어요.」에서 「누가」에 해당하는 말을 쓰세요.","answer":["다람쥐는"],"explanation":["눈이 동그래진 것은 다람쥐예요.","「다람쥐는」 뒤에서 조금 쉬어요.","「누가?」 물어요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"},"variant_rule":{"alt":[{"stem":"「아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.」에서 「누가」에 해당하는 말을 쓰세요.","answer":["아기 펭귄도","아기펭귄도"],"explanation":["뛰어든 것은 아기 펭귄이에요.","「아기 펭귄도」 뒤에서 조금 쉬어요.","「누가?」 물어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#9','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'essay','teacher','「다람쥐의 도토리」의 다람쥐에게 해 주고 싶은 말을, 무엇 때문에 무엇이 어떻게 되었는지 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C6","difficulty":4,"kind":"essay","stem":"「다람쥐의 도토리」의 다람쥐에게 해 주고 싶은 말을, 무엇 때문에 무엇이 어떻게 되었는지 넣어 쓰세요.","answer_guide":{"answer":"예: 다람쥐야, 네가 묻어 둔 도토리 덕분에 그 자리에 새 나무가 자라기 시작했어. — 다람쥐가 한 일과 그 결과가 함께 있으면 맞아요.","scoring_points":["다람쥐가 한 일이 있는가","그 일로 무엇이 어떻게 되었는지 있는가","「좋아」에서 그치지 않았는가"]},"explanation":["무엇 때문에 → 어떻게 되었나.","「잘했어」에서 멈추지 않아요.","이야기 내용으로 써요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L10_challenge#10','kor',1,2,'u6','L10','g1_2_kor_u6_L10_challenge','lesson_challenge','K1-2-u6-C6',4,'essay','teacher','「아기 펭귄의 첫 헤엄」을 짝에게 읽어 주려고 해요. 한 문장을 골라 쉬어 읽을 곳에 ∨ 표를 하여 쓰고, 그렇게 정한 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":4,"kind":"essay","stem":"「아기 펭귄의 첫 헤엄」을 짝에게 읽어 주려고 해요. 한 문장을 골라 쉬어 읽을 곳에 ∨ 표를 하여 쓰고, 그렇게 정한 까닭을 쓰세요.","answer_guide":{"answer":"예: 엄마 펭귄이 ∨ 먼저 물속으로 뛰어들었어요. 「누가」에 해당하는 「엄마 펭귄이」 뒤에서 쉬었어요. — 낱말 가운데가 아닌 곳에서 쉬고 까닭이 있으면 맞아요.","scoring_points":["∨ 표가 낱말 가운데가 아닌가","누가 뒤·뜻이 이어지는 곳에서 쉬었는가","까닭을 썼는가"]},"explanation":["누가 뒤에서 조금.","쉬는 곳은 여럿일 수 있어요.","까닭과 함께."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#1','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','물음표(?)로 끝나는 문장은 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],true,'{"seq":1,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"물음표(?)로 끝나는 문장은 어떻게 읽나요?","options":[{"t":"마지막 말을 살짝 올리며 물어보듯 읽는다","correct":true},{"t":"마지막 말을 힘주어 외치듯 읽는다","mis":"K1-2-u6-X18"},{"t":"마지막 말을 낮게 내려 끝맺듯 읽는다","mis":"K1-2-u6-X18"}],"explanation":["물음표는 끝을 올려요.","외치듯은 느낌표, 내려 끝맺기는 마침표예요.",". 차분 · ? 올림 · ! 힘줌."],"variant_rule":{"alt":[{"stem":"마침표(.)로 끝나는 문장은 어떻게 읽나요?","options":[{"t":"차분하게 끝을 맺으며 읽는다","correct":true},{"t":"끝을 올려 물어보듯 읽는다","mis":"K1-2-u6-X18"},{"t":"소리를 지르듯 힘주어 읽는다","mis":"K1-2-u6-X18"}],"explanation":["마침표는 차분하게 끝맺어요.","끝을 올리면 물음표, 힘주면 느낌표예요.",". 차분 · ? 올림 · ! 힘줌."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#2','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','「무당벌레야! 등에 까만 점이 있어!」는 어떻게 읽으면 좋을까요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":2,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「무당벌레야! 등에 까만 점이 있어!」는 어떻게 읽으면 좋을까요?","options":[{"t":"놀란 마음을 담아 힘주어 읽는다","correct":true},{"t":"졸린 듯 힘없이 읽는다","mis":"K1-2-u6-X18"},{"t":"묻듯이 끝을 올려 읽는다","mis":"K1-2-u6-X18"}],"explanation":["느낌표는 힘주어 읽어요.","힘없이 읽거나 끝을 올리면 마음이 안 전해져요.","느낌표 두 개를 봐요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#3','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','목소리 연극에서 대사는 어떻게 하나요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":3,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"목소리 연극에서 대사는 어떻게 하나요?","options":[{"t":"외우지 않고 대본을 보며 소리 내어 읽는다","correct":true},{"t":"대본 없이 모두 외워서 말한다","mis":"K1-2-u6-X19"},{"t":"몸짓으로만 보여 준다","mis":"K1-2-u6-X19"}],"explanation":["목소리 연극은 읽어서 하는 연극이에요.","외우거나 몸짓으로만 하는 것이 아니에요.","목소리로 뜻을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#4','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',1,'mc','auto','친구가 대사를 읽을 때 듣는 사람이 할 일은 무엇인가요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":4,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"친구가 대사를 읽을 때 듣는 사람이 할 일은 무엇인가요?","options":[{"t":"읽는 친구를 바라보며 조용히 듣는다","correct":true},{"t":"틀리면 크게 웃는다","mis":"K1-2-u6-X19"},{"t":"옆 친구와 이야기한다","mis":"K1-2-u6-X19"}],"explanation":["귀 기울여 들어야 친구가 편히 읽어요.","웃거나 떠들면 읽는 친구가 위축돼요.","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#5','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'match','auto','「교실에 온 무당벌레」에서 역할과 대사를 선으로 이어 보세요.','{}'::text[],true,'{"seq":5,"concept":"K1-2-u6-C7","difficulty":2,"kind":"match","stem":"「교실에 온 무당벌레」에서 역할과 대사를 선으로 이어 보세요.","pairs":[{"l":"지안","r":"어, 저게 뭐지?"},{"l":"서진","r":"무당벌레야! 등에 까만 점이 있어!"},{"l":"선생님","r":"손으로 잡지 말고 종이에 태워 보자."}],"mis":"K1-2-u6-X17","explanation":["대본에서 이름 옆의 말이 그 역할의 대사예요.","지안이는 묻고, 서진이는 알려 주고, 선생님은 방법을 말해요.","이름을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]},"variant_rule":{"alt":[{"stem":"「눈 오는 아침」에서 역할과 대사를 선으로 이어 보세요.","pairs":[{"l":"동생","r":"언니, 눈이 왔어!"},{"l":"언니","r":"정말? 우리 눈사람 만들까?"},{"l":"엄마","r":"장갑부터 끼고 나가렴."}],"explanation":["대본에서 이름 옆의 말이 그 역할의 대사예요.","동생은 알리고, 언니는 묻고, 엄마는 일러 줘요.","이름을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#6','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'mc','auto','「정말? 우리 눈사람 만들까?」를 읽는 방법으로 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":6,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"「정말? 우리 눈사람 만들까?」를 읽는 방법으로 알맞은 것은 어느 것인가요?","options":[{"t":"「정말?」과 「만들까?」 모두 끝을 살짝 올려 읽는다","correct":true},{"t":"두 군데 모두 끝을 내려 차분하게 읽는다","mis":"K1-2-u6-X18"},{"t":"물음표는 빼고 한 번에 빠르게 읽는다","mis":"K1-2-u6-X18"}],"explanation":["물음표가 두 번 있어요.","둘 다 끝을 올려 묻듯이.","부호를 하나씩 살려요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#7','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'mc','auto','친구의 목소리 연극에서 살펴볼 것은 어느 것인가요?',ARRAY['K1-2-u6-X19']::text[],true,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"친구의 목소리 연극에서 살펴볼 것은 어느 것인가요?","options":[{"t":"문장 부호를 살려 읽었는지","correct":true},{"t":"옷이 멋진지","mis":"K1-2-u6-X19"},{"t":"누가 제일 빨리 끝냈는지","mis":"K1-2-u6-X19"}],"explanation":["읽기에 관한 것을 살펴요.","옷이나 빠르기는 읽기와 상관없어요.","뜻·쉬기·부호."],"variant_rule":{"alt":[{"stem":"이번에는 다른 보기예요. 친구의 목소리 연극에서 살펴볼 것은 어느 것인가요?","options":[{"t":"뜻이 통하게 쉬어 읽었는지","correct":true},{"t":"목소리가 누가 제일 큰지","mis":"K1-2-u6-X19"},{"t":"머리 모양이 어떤지","mis":"K1-2-u6-X19"}],"explanation":["읽기에 관한 것을 살펴요.","목소리 크기, 머리 모양은 기준이 아니에요.","뜻·쉬기·부호."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#8','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',2,'ox','auto','문장 부호에 맞게 읽으면 인물의 마음까지 전할 수 있어요.',ARRAY['K1-2-u6-X18']::text[],true,'{"seq":8,"concept":"K1-2-u6-C7","difficulty":2,"kind":"ox","stem":"문장 부호에 맞게 읽으면 인물의 마음까지 전할 수 있어요.","answer":"O","reason_options":[{"t":"물음·놀람·차분함이 목소리에 실리니까","correct":true},{"t":"부호는 눈으로만 보는 것이니까","mis":"K1-2-u6-X18"}],"mis":"K1-2-u6-X18","explanation":["부호가 마음을 알려 줘요.","소리 내어 읽을 때 살려요.",". ? ! 를 살려요."],"variant_rule":{"alt":[{"stem":"느낌표가 있어도 마침표처럼 똑같이 읽으면 돼요.","answer":"X","reason_options":[{"t":"느낌표는 힘주어 읽어야 마음이 전해지니까","correct":true},{"t":"부호가 달라도 읽는 법은 같으니까","mis":"K1-2-u6-X18"}],"explanation":["느낌표는 힘주어 읽어요.","마침표처럼 읽으면 놀람이 안 전해져요.","부호마다 달라요."],"asset":null}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#9','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C5',2,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「무당벌레는 종이를 타고 창밖으로 날아갔어요.」를 뜻이 통하게 읽은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":9,"concept":"K1-2-u6-C5","difficulty":2,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「무당벌레는 종이를 타고 창밖으로 날아갔어요.」를 뜻이 통하게 읽은 것은 어느 것인가요?","options":[{"t":"무당벌레는 ∨ 종이를 타고 창밖으로 날아갔어요.","correct":true},{"t":"무당 ∨ 벌레는 종이를 타 ∨ 고 창밖으로 날아갔어요.","mis":"K1-2-u6-X13"},{"t":"무당벌레는종이를타고창밖으로날아갔어요.","mis":"K1-2-u6-X14"}],"explanation":["「누가」 뒤에서 조금 쉬었어요.","낱말을 자르거나 붙이면 안 돼요.","연극에서도 띄어 읽기."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_basic#10','kor',1,2,'u6','L13','g1_2_kor_u6_L13_basic','lesson_basic','K1-2-u6-C7',3,'error','auto','목소리 연극을 할 때 지킬 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#1','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',2,'mc','auto','「장갑부터 끼고 나가렴.」은 누구의 대사인가요?',ARRAY['K1-2-u6-X17']::text[],false,'{"seq":1,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"「장갑부터 끼고 나가렴.」은 누구의 대사인가요?","options":[{"t":"엄마","correct":true},{"t":"언니","mis":"K1-2-u6-X17"},{"t":"해설","mis":"K1-2-u6-X17"}],"explanation":["대본에서 엄마의 말이에요.","언니는 묻고, 해설은 장면을 알려 줘요.","이름을 짚어요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#2','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',2,'ox','auto','친구의 읽기를 살필 때에는 목소리가 가장 큰 사람을 고르면 돼요.',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":2,"concept":"K1-2-u6-C7","difficulty":2,"kind":"ox","stem":"친구의 읽기를 살필 때에는 목소리가 가장 큰 사람을 고르면 돼요.","answer":"X","reason_options":[{"t":"크기보다 뜻이 통하게 읽었는지가 중요하니까","correct":true},{"t":"큰 목소리가 가장 잘 읽은 것이니까","mis":"K1-2-u6-X19"}],"mis":"K1-2-u6-X19","explanation":["읽기에 관한 것을 살펴요.","목소리 크기 겨루기가 아니에요.","뜻·쉬기·부호."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#3','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','서진이의 대사에는 느낌표가 두 번 있어요. 이 대사에서 알 수 있는 서진이의 마음은 무엇인가요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":3,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"서진이의 대사에는 느낌표가 두 번 있어요. 이 대사에서 알 수 있는 서진이의 마음은 무엇인가요?","options":[{"t":"무당벌레를 보고 반갑고 놀란 마음","correct":true},{"t":"무당벌레가 무서워 슬픈 마음","mis":"K1-2-u6-X18"},{"t":"아무 느낌이 없는 마음","mis":"K1-2-u6-X18"}],"explanation":["「무당벌레야!」는 반가움과 놀람이에요.","슬프거나 아무 느낌이 없으면 느낌표를 쓰지 않아요.","부호가 마음을 알려 줘요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#4','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','해설은 어떻게 읽으면 좋을까요?',ARRAY['K1-2-u6-X18','K1-2-u6-X14']::text[],false,'{"seq":4,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"해설은 어떻게 읽으면 좋을까요?","options":[{"t":"듣는 사람이 장면을 떠올리게 차분하고 또렷하게","correct":true},{"t":"인물처럼 소리를 지르며","mis":"K1-2-u6-X18"},{"t":"빨리 끝내려고 쉬지 않고","mis":"K1-2-u6-X14"}],"explanation":["해설은 장면을 알려 주는 말이에요.","소리를 지르거나 쉬지 않으면 장면이 그려지지 않아요.","마침표로 끝나요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#5','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'error','auto','친구의 목소리 연극에서 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#6','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','「어, 저게 뭐지?」에서 「어,」 뒤의 쉼표(,)는 어떻게 읽으면 좋을까요?',ARRAY['K1-2-u6-X14','K1-2-u6-X18']::text[],false,'{"seq":6,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"「어, 저게 뭐지?」에서 「어,」 뒤의 쉼표(,)는 어떻게 읽으면 좋을까요?","options":[{"t":"짧게 한 번 쉬었다가 읽는다","correct":true},{"t":"쉼표를 빼고 붙여 읽는다","mis":"K1-2-u6-X14"},{"t":"끝을 올려 묻듯이 읽는다","mis":"K1-2-u6-X18"}],"explanation":["쉼표에서는 짧게 쉬어요.","끝을 올리는 것은 물음표 자리예요.","부호마다 읽는 법이 달라요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#7','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',3,'mc','auto','도하가 라온이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X19','K1-2-u6-X18']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":3,"kind":"mc","stem":"도하가 라온이에게 해 줄 말로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"신난 마음이니까 대본처럼 느낌표를 살려 힘주어 읽어 보자.","correct":true},{"t":"목소리가 작으니까 넌 빼고 하자.","mis":"K1-2-u6-X19"},{"t":"물음표처럼 끝을 올려 읽어 보자.","mis":"K1-2-u6-X18"}],"explanation":["대본에는 「언니, 눈이 왔어!」 — 느낌표예요.","친구를 빼는 말은 듣는 예절이 아니에요.","부호를 살리게 도와요."],"asset":{"type":"speech","turns":[{"who":"라온","text":"(작고 힘없는 목소리로) 언니, 눈이 왔어."},{"who":"도하","text":"라온아, 대본을 다시 볼래?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#8','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',4,'sa','auto','물음표가 있는 문장은 끝을 어떻게 읽나요? 빈칸에 알맞은 말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#9','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',4,'essay','teacher','「눈 오는 아침」에서 맡고 싶은 역할을 하나 고르고, 그 역할의 대사 하나를 어떻게 읽을지 문장 부호와 마음을 넣어 쓰세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C7","difficulty":4,"kind":"essay","stem":"「눈 오는 아침」에서 맡고 싶은 역할을 하나 고르고, 그 역할의 대사 하나를 어떻게 읽을지 문장 부호와 마음을 넣어 쓰세요.","answer_guide":{"answer":"예: 동생 역할. 「언니, 눈이 왔어!」는 느낌표가 있으니까 신난 마음을 담아 힘주어 읽을 거예요. — 역할·대사·부호에 맞는 읽는 법이 있으면 맞아요.","scoring_points":["역할과 대사를 바르게 짝지었는가","문장 부호에 맞는 읽는 법인가","인물의 마음을 썼는가"]},"explanation":["역할 + 대사 + 읽는 법.","부호를 살펴요.","마음을 담아요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_L13_challenge#10','kor',1,2,'u6','L13','g1_2_kor_u6_L13_challenge','lesson_challenge','K1-2-u6-C7',4,'essay','teacher','친구가 「어, 저게 뭐지?」는 끝을 올려 읽고, 「무당벌레야!」는 힘주어 읽었어요. 이 친구에게 잘한 점을 읽기에 관한 것으로 한 문장 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C7","difficulty":4,"kind":"essay","stem":"친구가 「어, 저게 뭐지?」는 끝을 올려 읽고, 「무당벌레야!」는 힘주어 읽었어요. 이 친구에게 잘한 점을 읽기에 관한 것으로 한 문장 쓰세요.","answer_guide":{"answer":"예: 물음표와 느낌표를 살려 읽어서 놀란 마음이 잘 들렸어. — 읽기(부호·쉬기·뜻)에 관한 잘한 점이면 맞아요.","scoring_points":["읽기에 관한 잘한 점인가","무엇을 잘했는지 구체적인가","친구를 존중하는 말인가"]},"explanation":["읽기에 관한 것만.","옷·목소리 크기가 아니에요.","구체적으로 칭찬해요."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#1','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',1,'mc','auto','그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?","options":[{"t":"책 읽는 친구들이 집중할 수 있게 작은 목소리로 말하자.","correct":true},{"t":"시끄러워.","mis":"K1-2-u6-X01"},{"t":"저리 가.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","느낌만, 까닭 없는 말은 잘 통하지 않아요.","「~하니까 ~하자」."],"asset":{"type":"scene","icon":"📚","text":"도서관에서 한 친구가 큰 소리로 떠들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#2','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',1,'mc','auto','지안이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"지안이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?","options":[{"t":"에어컨을 켤 때에는 창문을 닫아요.","correct":true},{"t":"에어컨을 켰는데 창문이 열려 있어요.","mis":"K1-2-u6-X06"},{"t":"시원한 바람이 밖으로 빠져나가니까 창문을 닫으면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 에어컨을 켰는데 창문이 열려 있어요.","해결 방법: 에어컨을 켤 때에는 창문을 닫아요.","자신의 생각: 시원한 바람이 밖으로 빠져나가니까 창문을 닫으면 좋겠어요."],"title":"지안이가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#3','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',1,'mc','auto','이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?","options":[{"t":"사과 하나를 동그랗게 그려요","correct":true},{"t":"하늘 가득 무지개를 그려요","mis":"K1-2-u6-X08"},{"t":"크레파스 일곱이 모이면","mis":"K1-2-u6-X08"}],"explanation":["크레파스 하나가 혼자 그린 것이에요.","무지개는 모였을 때예요.","하나 / 모임을 나누어요."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#4','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C4',1,'mc','auto','[솓]이라고 소리 나는, 밥을 짓는 그릇을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"[솓]이라고 소리 나는, 밥을 짓는 그릇을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"솥","correct":true},{"t":"솓","mis":"K1-2-u6-X10"},{"t":"솟","mis":"K1-2-u6-X10"}],"explanation":["글자는 「솥」이에요.","소리대로 쓰지 않아요.","받침 ㅌ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#5','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"교실에서는 ∨ 천천히 걸어 다녀요.","correct":true},{"t":"교실에서는천천히걸어다녀요.","mis":"K1-2-u6-X14"},{"t":"교 ∨ 실에서는 천천히 걸 ∨ 어 다녀요.","mis":"K1-2-u6-X13"}],"explanation":["덩어리로 묶어 읽었어요.","붙이거나 낱말을 자르면 안 돼요.","낱말은 한 덩어리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#6','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',1,'mc','auto','「다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"다람쥐가","correct":true},{"t":"도토리를","mis":"K1-2-u6-X16"},{"t":"겨울을","mis":"K1-2-u6-X16"}],"explanation":["묻은 것은 다람쥐예요.","도토리는 무엇을, 겨울은 때예요.","「누가?」 물어요."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#7','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C7',1,'mc','auto','「어, 저게 뭐지?」는 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「어, 저게 뭐지?」는 어떻게 읽나요?","options":[{"t":"끝을 살짝 올려 물어보듯 읽는다","correct":true},{"t":"끝을 낮게 내려 끝맺듯 읽는다","mis":"K1-2-u6-X18"},{"t":"힘주어 외치듯 읽는다","mis":"K1-2-u6-X18"}],"explanation":["물음표는 끝을 올려요.","내리면 마침표, 외치면 느낌표예요.","? 올림."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#8','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C8',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#9','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C4',2,'match','auto','낱말과 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"솥","r":"[솓]"},{"l":"곁","r":"[겯]"},{"l":"늪","r":"[늡]"}],"mis":"K1-2-u6-X10","explanation":["글자와 소리가 달라요.","솥[솓] · 곁[겯] · 늪[늡].","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#10','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',2,'match','auto','「다람쥐의 도토리」에서 차례와 있었던 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「다람쥐의 도토리」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"도토리를 땅에 묻었어요"},{"l":"가운데","r":"묻은 곳을 잊어버렸어요"},{"l":"끝","r":"그 자리에서 싹이 돋았어요"}],"mis":"K1-2-u6-X17","explanation":["묻고 → 잊고 → 싹.","「그런데」, 「봄이 왔어요」.","줄 차례."],"asset":{"type":"passage","lines":["다람쥐가 겨울을 앞두고 도토리를 땅에 묻었어요.","그런데 다람쥐는 묻은 곳을 깜빡 잊어버렸어요.","눈이 녹고 봄이 왔어요.","도토리를 묻은 자리에서 작은 싹이 돋았어요.","다람쥐는 싹을 보고 눈이 동그래졌어요."],"title":"「다람쥐의 도토리」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#11','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',2,'mc','auto','라온이가 「뭘? 왜?」 하고 되물은 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X02']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"라온이가 「뭘? 왜?」 하고 되물은 까닭은 무엇인가요?","options":[{"t":"무엇을 왜 하지 말라는지 알 수 없어서","correct":true},{"t":"수아의 말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"수아가 문장 부호를 안 썼다고 생각해서","mis":"K1-2-u6-X02"}],"explanation":["무엇을, 왜가 빠졌어요.","길어서가 아니라 짧아서예요.","무엇을 왜."],"asset":{"type":"speech","turns":[{"who":"수아","text":"그거 하지 마."},{"who":"라온","text":"뭘? 왜?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#12','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',2,'mc','auto','「교실 문을 세게 닫아 큰 소리가 나요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「교실 문을 세게 닫아 큰 소리가 나요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"문고리를 잡고 살살 닫아요.","correct":true},{"t":"문을 아예 열지 않아요.","mis":"K1-2-u6-X05"},{"t":"문을 떼어 내요.","mis":"K1-2-u6-X05"}],"explanation":["살살 닫으면 소리가 안 나요.","열지 않거나 떼어 내는 것은 방법이 아니에요.","지금 할 수 있는 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#13','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',2,'mc','auto','시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X08']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"혼자 그린 사과도 예쁘지만, 친구들과 함께 그리면 더 큰 그림이 될 것 같아요.","correct":true},{"t":"좋았어요.","mis":"K1-2-u6-X01"},{"t":"사과 하나를 동그랗게 그려요.","mis":"K1-2-u6-X08"}],"explanation":["내 생각이 내 말로 드러나요.","한마디나 시를 옮긴 말은 생각이 아니에요.","「나도 ~」."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#14','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C7',2,'mc','auto','친구가 목소리 연극을 할 때 살펴볼 것은 어느 것인가요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"친구가 목소리 연극을 할 때 살펴볼 것은 어느 것인가요?","options":[{"t":"뜻이 통하게 쉬어 읽었는지","correct":true},{"t":"누가 가장 빨리 읽었는지","mis":"K1-2-u6-X19"},{"t":"옷을 어떻게 입었는지","mis":"K1-2-u6-X19"}],"explanation":["읽기에 관한 것을 살펴요.","빠르기, 옷은 상관없어요.","뜻·쉬기·부호."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#15','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C5',2,'ox','auto','쉬어 읽는 곳은 문장마다 딱 한 군데로 정해져 있어요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"쉬어 읽는 곳은 문장마다 딱 한 군데로 정해져 있어요.","answer":"X","reason_options":[{"t":"뜻이 통하면 쉬는 곳은 여럿일 수 있으니까","correct":true},{"t":"정답은 언제나 하나뿐이니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["쉬는 곳은 여럿일 수 있어요.","뜻이 통하는지가 기준이에요.","친구와 달라도 괜찮아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
