INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#19','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C2',3,'ox','auto','세 칸 생각에서 「자신의 생각」 칸에는 까닭을 넣지 않아도 돼요.',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"세 칸 생각에서 「자신의 생각」 칸에는 까닭을 넣지 않아도 돼요.","answer":"X","reason_options":[{"t":"왜 그렇게 생각했는지가 있어야 생각이 잘 전해지니까","correct":true},{"t":"까닭은 「문제」 칸에만 쓰는 것이니까","mis":"K1-2-u6-X06"}],"mis":"K1-2-u6-X02","explanation":["자신의 생각에는 까닭을 넣어요.","「~니까 ~면 좋겠어요」.","까닭이 생각을 전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#20','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C6',3,'mc','auto','「누가·무엇이」에 해당하는 말이 길 때 알맞은 읽기는 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"「누가·무엇이」에 해당하는 말이 길 때 알맞은 읽기는 어느 것인가요?","options":[{"t":"그 말 안에서도 한 번 더 쉬어 읽는다","correct":true},{"t":"긴 말은 숨을 참고 쉬지 않고 읽는다","mis":"K1-2-u6-X14"},{"t":"낱말 가운데를 잘라 쉰다","mis":"K1-2-u6-X13"}],"explanation":["길면 한 번 더 쉬어요.","숨을 참거나 낱말을 자르면 안 돼요.","누가 뒤 조금, 길면 한 번 더."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#21','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C7',3,'error','auto','친구의 목소리 연극에서 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#22','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',3,'mc','auto','시 「크레파스」의 「하늘 가득 무지개를 그려요」가 알려 주는 것은 무엇인가요?',ARRAY['K1-2-u6-X09','K1-2-u6-X08']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「크레파스」의 「하늘 가득 무지개를 그려요」가 알려 주는 것은 무엇인가요?","options":[{"t":"여럿이 모이면 혼자서는 못 하는 큰일을 할 수 있다","correct":true},{"t":"빨강 하나로는 아무것도 못 그린다","mis":"K1-2-u6-X09"},{"t":"무지개는 한 가지 색이다","mis":"K1-2-u6-X08"}],"explanation":["일곱이 모여 무지개를 그렸어요.","하나로도 사과를 그렸으니 못 그리는 게 아니에요.","둘 다 소중해요."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#23','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C8',4,'sa','auto','「넓다」의 반대말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#24','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C1',4,'essay','teacher','그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 책 읽는 친구들이 집중할 수 있게 작은 목소리로 이야기하자. — 할 일과 까닭이 함께 있으면 맞아요.","scoring_points":["무엇을 어떻게 하자는지 있는가","까닭이 있는가","나무라지 않고 받아들이기 쉬운 말인가"]},"explanation":["할 일 + 까닭.","「하지 마」 대신 「~하자」.","친구가 고개를 끄덕일 말."],"asset":{"type":"scene","icon":"📚","text":"도서관에서 한 친구가 큰 소리로 떠들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_a#25','kor',1,2,'u6','','g1_2_kor_u6_review_a','unit_review','K1-2-u6-C3',4,'essay','teacher','「크레파스」를 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"「크레파스」를 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.","answer_guide":{"answer":"예: 혼자 그린 사과도 예뻐요. 모이면 무지개가 되는 게 멋져요. 나는 모둠 그림을 그릴 때 내 몫을 끝까지 칠하겠어요. — 시에서 온 생각과 할 일이 짧은 문장으로 있으면 맞아요.","scoring_points":["시에서 온 생각이 내 말로 있는가","우리 반을 위한 할 일(무엇을·언제)이 있는가","짧은 문장 여러 개로 나누었는가"]},"explanation":["짧은 문장 여러 개.","시를 옮기지 말고 내 말로.","할 일은 구체적으로."],"asset":{"type":"passage","lines":["빨강 크레파스 혼자서","사과 하나를 동그랗게 그려요","크레파스 일곱이 모이면","하늘 가득 무지개를 그려요"],"title":"「크레파스」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#1','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C1',1,'mc','auto','그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?","options":[{"t":"버스가 멈출 때 넘어질 수 있으니까 손잡이를 꼭 잡자.","correct":true},{"t":"위험해.","mis":"K1-2-u6-X01"},{"t":"그러지 마.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","느낌만, 까닭 없는 말은 잘 통하지 않아요.","「~하니까 ~하자」."],"asset":{"type":"scene","icon":"🚌","text":"버스가 달리는데 한 친구가 손잡이를 잡지 않고 서 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#2','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C2',1,'mc','auto','서진이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"서진이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?","options":[{"t":"필요한 만큼만 뜯어 써요.","correct":true},{"t":"손을 닦을 때 화장지를 길게 많이 뜯어요.","mis":"K1-2-u6-X06"},{"t":"버려지는 화장지가 줄어드니까 조금씩 쓰면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 손을 닦을 때 화장지를 길게 많이 뜯어요.","해결 방법: 필요한 만큼만 뜯어 써요.","자신의 생각: 버려지는 화장지가 줄어드니까 조금씩 쓰면 좋겠어요."],"title":"서진이가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#3','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',1,'mc','auto','이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?","options":[{"t":"혼자서도 물소리를 들으며 앉아 있어요","correct":true},{"t":"친구들이 건너는 길이 되어요","mis":"K1-2-u6-X08"},{"t":"돌이 줄지어 놓이면","mis":"K1-2-u6-X08"}],"explanation":["돌 하나의 모습이에요.","길은 돌이 모였을 때예요.","하나 / 모임을 나누어요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#4','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C4',1,'mc','auto','[겯]이라고 소리 나는, 바로 옆을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"[겯]이라고 소리 나는, 바로 옆을 뜻하는 낱말을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"곁","correct":true},{"t":"겯","mis":"K1-2-u6-X10"},{"t":"겻","mis":"K1-2-u6-X10"}],"explanation":["글자는 「곁」이에요.","소리대로 쓰지 않아요.","받침 ㅌ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#5','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"쉬는 시간에는 ∨ 운동장에서 공놀이를 해요.","correct":true},{"t":"쉬는시간에는운동장에서공놀이를해요.","mis":"K1-2-u6-X14"},{"t":"쉬는 시 ∨ 간에는 운동장에서 공놀 ∨ 이를 해요.","mis":"K1-2-u6-X13"}],"explanation":["덩어리로 묶어 읽었어요.","붙이거나 낱말을 자르면 안 돼요.","낱말은 한 덩어리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#6','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C6',1,'mc','auto','「엄마 펭귄이 먼저 물속으로 뛰어들었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「엄마 펭귄이 먼저 물속으로 뛰어들었어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"엄마 펭귄이","correct":true},{"t":"물속으로","mis":"K1-2-u6-X16"},{"t":"먼저","mis":"K1-2-u6-X16"}],"explanation":["뛰어든 것은 엄마 펭귄이에요.","물속으로는 어디로, 먼저는 언제예요.","「누가?」 물어요."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#7','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C7',1,'mc','auto','「언니, 눈이 왔어!」는 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「언니, 눈이 왔어!」는 어떻게 읽나요?","options":[{"t":"신난 마음을 담아 힘주어 읽는다","correct":true},{"t":"끝을 올려 물어보듯 읽는다","mis":"K1-2-u6-X18"},{"t":"힘없이 작게 읽는다","mis":"K1-2-u6-X18"}],"explanation":["느낌표는 힘주어 읽어요.","끝을 올리면 물음표처럼 들려요.","! 힘줌."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
