INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#9','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C4',2,'match','auto','낱말과 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"엿","r":"[엳]"},{"l":"붓","r":"[붇]"},{"l":"볕","r":"[볃]"}],"mis":"K1-2-u6-X10","explanation":["글자와 소리가 달라요.","엿[엳] · 붓[붇] · 볕[볃].","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#10','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C6',2,'match','auto','「아기 펭귄의 첫 헤엄」에서 차례와 있었던 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「아기 펭귄의 첫 헤엄」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"발만 담갔다가 뺐어요"},{"l":"가운데","r":"엄마 펭귄이 먼저 뛰어들었어요"},{"l":"끝","r":"용기를 내어 뛰어들어 헤엄쳤어요"}],"mis":"K1-2-u6-X17","explanation":["망설임 → 엄마 먼저 → 아기도.","「먼저」, 「도」.","줄 차례."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#11','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C1',2,'mc','auto','로아가 「뭐가?」 하고 되물은 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X02']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"로아가 「뭐가?」 하고 되물은 까닭은 무엇인가요?","options":[{"t":"무엇이 왜 위험하고 어떻게 하면 좋을지 없어서","correct":true},{"t":"도하의 말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"도하가 웃으며 말해서","mis":"K1-2-u6-X02"}],"explanation":["느낌만 있어요.","무엇이 왜, 어떻게가 빠졌어요.","느낌에서 한 걸음 더."],"asset":{"type":"speech","turns":[{"who":"도하","text":"위험해!"},{"who":"로아","text":"뭐가?"}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#12','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C2',2,'mc','auto','「손을 씻고 물기를 바닥에 털어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「손을 씻고 물기를 바닥에 털어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"손수건으로 물기를 닦아요.","correct":true},{"t":"바닥이 마를 때까지 기다려요.","mis":"K1-2-u6-X05"},{"t":"물을 더 세게 틀어요.","mis":"K1-2-u6-X05"}],"explanation":["닦으면 바닥이 젖지 않아요.","기다리거나 물을 세게 틀면 그대로예요.","지금 할 수 있는 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#13','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',2,'mc','auto','시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X08']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나도 징검돌처럼 친구가 어려울 때 건너게 도와주고 싶어요.","correct":true},{"t":"좋았어요.","mis":"K1-2-u6-X01"},{"t":"친구들이 건너는 길이 되어요.","mis":"K1-2-u6-X08"}],"explanation":["내 생각이 내 말로 드러나요.","한마디나 시를 옮긴 말은 생각이 아니에요.","「나도 ~」."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#14','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C7',2,'mc','auto','친구가 목소리 연극을 할 때 살펴볼 것은 어느 것인가요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"친구가 목소리 연극을 할 때 살펴볼 것은 어느 것인가요?","options":[{"t":"문장 부호를 살려 읽었는지","correct":true},{"t":"목소리가 누가 제일 큰지","mis":"K1-2-u6-X19"},{"t":"머리 모양이 어떤지","mis":"K1-2-u6-X19"}],"explanation":["읽기에 관한 것을 살펴요.","목소리 크기, 머리 모양은 상관없어요.","뜻·쉬기·부호."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#15','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C5',2,'ox','auto','띄어 쓴 곳마다 모두 쉬어 읽어야 자연스러워요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"띄어 쓴 곳마다 모두 쉬어 읽어야 자연스러워요.","answer":"X","reason_options":[{"t":"띄어 쓴 곳마다 쉬면 뚝뚝 끊겨 들리니까","correct":true},{"t":"띄어 쓴 곳이 바로 쉬는 곳이니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["덩어리로 묶어 읽어요.","띄어 쓴 곳마다 쉬지 않아요.","쉬는 곳은 뜻으로."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
