INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#19','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C2',3,'ox','auto','「해결 방법」 칸에는 지금 내가 할 수 있는 일을 쓰면 좋아요.',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"「해결 방법」 칸에는 지금 내가 할 수 있는 일을 쓰면 좋아요.","answer":"O","reason_options":[{"t":"할 수 있는 일이어야 문제가 실제로 풀리니까","correct":true},{"t":"어렵고 큰일을 써야 멋진 생각이니까","mis":"K1-2-u6-X05"}],"mis":"K1-2-u6-X05","explanation":["내가 할 수 있는 일로.","멋진 것보다 되는 것.","오늘 바로 할 수 있나요?"]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#20','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C6',3,'mc','auto','「아기 펭귄이 바닷가에 섰어요.」와 다음 문장 사이는 어떻게 읽나요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"「아기 펭귄이 바닷가에 섰어요.」와 다음 문장 사이는 어떻게 읽나요?","options":[{"t":"조금 더 쉬었다가 다음 문장을 읽는다","correct":true},{"t":"쉬지 않고 붙여 읽는다","mis":"K1-2-u6-X14"},{"t":"다음 문장의 낱말 가운데에서 쉰다","mis":"K1-2-u6-X13"}],"explanation":["문장 사이에서는 조금 더 쉬어요.","붙이거나 낱말을 자르면 안 돼요.","마침표에서 숨 고르기."],"asset":{"type":"passage","lines":["아기 펭귄이 바닷가에 섰어요.","물이 차가워서 발만 담갔다가 얼른 뺐어요.","엄마 펭귄이 먼저 물속으로 뛰어들었어요.","아기 펭귄도 용기를 내어 첨벙 뛰어들었어요.","물속에서 아기 펭귄은 새처럼 빠르게 헤엄쳤어요."],"title":"「아기 펭귄의 첫 헤엄」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#21','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C7',3,'error','auto','목소리 연극을 할 때 지킬 일을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#22','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',3,'mc','auto','시 「징검돌」의 「친구들이 건너는 길이 되어요」가 뜻하는 것은 무엇인가요?',ARRAY['K1-2-u6-X09','K1-2-u6-X08']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「징검돌」의 「친구들이 건너는 길이 되어요」가 뜻하는 것은 무엇인가요?","options":[{"t":"모이면 다른 사람을 도울 수 있다","correct":true},{"t":"돌 하나는 쓸모가 없다","mis":"K1-2-u6-X09"},{"t":"냇물이 말라 버린다","mis":"K1-2-u6-X08"}],"explanation":["모인 돌이 친구를 건너게 해요.","돌 하나도 제 모습이 있어요.","둘 다 소중해요."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#23','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C8',4,'sa','auto','「빠르다」의 반대말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#24','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C1',4,'essay','teacher','그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 버스가 갑자기 멈추면 넘어질 수 있으니까 손잡이를 꼭 잡자. — 할 일과 까닭이 함께 있으면 맞아요.","scoring_points":["무엇을 어떻게 하자는지 있는가","까닭이 있는가","나무라지 않고 받아들이기 쉬운 말인가"]},"explanation":["할 일 + 까닭.","「하지 마」 대신 「~하자」.","친구가 고개를 끄덕일 말."],"asset":{"type":"scene","icon":"🚌","text":"버스가 달리는데 한 친구가 손잡이를 잡지 않고 서 있어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_b#25','kor',1,2,'u6','','g1_2_kor_u6_review_b','unit_review','K1-2-u6-C3',4,'essay','teacher','「징검돌」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"「징검돌」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.","answer_guide":{"answer":"예: 돌 하나도 혼자 물소리를 들어요. 모이면 길이 되어요. 나는 친구가 숙제를 어려워하면 옆에서 같이 해 주겠어요. — 시에서 온 생각과 할 일이 짧은 문장으로 있으면 맞아요.","scoring_points":["시에서 온 생각이 내 말로 있는가","우리 반을 위한 할 일(무엇을·언제)이 있는가","짧은 문장 여러 개로 나누었는가"]},"explanation":["짧은 문장 여러 개.","시를 옮기지 말고 내 말로.","할 일은 구체적으로."],"asset":{"type":"passage","lines":["냇물 위에 돌 하나","혼자서도 물소리를 들으며 앉아 있어요","돌이 줄지어 놓이면","친구들이 건너는 길이 되어요"],"title":"「징검돌」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#1','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',1,'mc','auto','그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?","options":[{"t":"먼저 와서 기다린 친구들이 있으니까 맨 뒤에 서자.","correct":true},{"t":"얄미워.","mis":"K1-2-u6-X01"},{"t":"하지 마.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","느낌만, 까닭 없는 말은 잘 통하지 않아요.","「~하니까 ~하자」."],"asset":{"type":"scene","icon":"🍱","text":"급식실에서 한 친구가 줄 앞에 끼어들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#2','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',1,'mc','auto','로아의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"로아의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?","options":[{"t":"다 쓰면 바로 뚜껑을 닫아요.","correct":true},{"t":"사인펜 뚜껑을 열어 둔 채 놀러 나가요.","mis":"K1-2-u6-X06"},{"t":"사인펜이 마르면 더 쓸 수 없으니까 뚜껑을 꼭 닫으면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 사인펜 뚜껑을 열어 둔 채 놀러 나가요.","해결 방법: 다 쓰면 바로 뚜껑을 닫아요.","자신의 생각: 사인펜이 마르면 더 쓸 수 없으니까 뚜껑을 꼭 닫으면 좋겠어요."],"title":"로아가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#3','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',1,'mc','auto','이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?","options":[{"t":"바람을 타고 빙그르르 춤을 춰요","correct":true},{"t":"여름 나무 아래 시원한 그늘이 되어요","mis":"K1-2-u6-X08"},{"t":"나뭇잎이 모이고 모여","mis":"K1-2-u6-X08"}],"explanation":["나뭇잎 하나의 모습이에요.","그늘은 모였을 때예요.","하나 / 모임을 나누어요."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#4','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C4',1,'mc','auto','[엳]이라고 소리 나는, 달콤한 먹을거리를 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"[엳]이라고 소리 나는, 달콤한 먹을거리를 바르게 쓴 것은 어느 것인가요?","options":[{"t":"엿","correct":true},{"t":"엳","mis":"K1-2-u6-X10"},{"t":"엇","mis":"K1-2-u6-X10"}],"explanation":["글자는 「엿」이에요.","소리대로 쓰지 않아요.","받침 ㅅ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#5','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"점심을 먹고 나면 ∨ 이를 닦아요.","correct":true},{"t":"점심을먹고나면이를닦아요.","mis":"K1-2-u6-X14"},{"t":"점 ∨ 심을 먹고 나 ∨ 면 이를 닦아요.","mis":"K1-2-u6-X13"}],"explanation":["덩어리로 묶어 읽었어요.","붙이거나 낱말을 자르면 안 돼요.","낱말은 한 덩어리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#6','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',1,'mc','auto','「달팽이는 아주 천천히 풀잎을 기어올랐어요.」에서 「누가」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「달팽이는 아주 천천히 풀잎을 기어올랐어요.」에서 「누가」에 해당하는 말은 어느 것인가요?","options":[{"t":"달팽이는","correct":true},{"t":"풀잎을","mis":"K1-2-u6-X16"},{"t":"천천히","mis":"K1-2-u6-X16"}],"explanation":["기어오른 것은 달팽이예요.","풀잎은 무엇을, 천천히는 어떻게예요.","「누가?」 물어요."],"asset":{"type":"passage","lines":["비 온 뒤 달팽이가 집을 지고 길을 나섰어요.","달팽이는 아주 천천히 풀잎을 기어올랐어요.","개미가 \"그렇게 느려서 언제 가니?\" 하고 물었어요.","달팽이는 쉬지 않고 한 걸음씩 나아갔어요.","저녁이 되자 달팽이는 커다란 버섯 아래에 닿았어요."],"title":"「달팽이의 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#7','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',1,'mc','auto','「손으로 잡지 말고 종이에 태워 보자.」는 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「손으로 잡지 말고 종이에 태워 보자.」는 어떻게 읽나요?","options":[{"t":"차분하게 끝을 맺으며 읽는다","correct":true},{"t":"끝을 올려 물어보듯 읽는다","mis":"K1-2-u6-X18"},{"t":"소리를 지르듯 읽는다","mis":"K1-2-u6-X18"}],"explanation":["마침표는 차분하게 읽어요.","올리면 물음, 지르면 느낌표예요.",". 차분."],"asset":{"type":"speech","turns":[{"who":"해설","text":"창문 틈으로 무당벌레 한 마리가 들어왔어요."},{"who":"지안","text":"어, 저게 뭐지?"},{"who":"서진","text":"무당벌레야! 등에 까만 점이 있어!"},{"who":"선생님","text":"손으로 잡지 말고 종이에 태워 보자."},{"who":"해설","text":"무당벌레는 종이를 타고 창밖으로 날아갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#8','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C8',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#9','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C4',2,'match','auto','낱말과 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"밑","r":"[믿]"},{"l":"늪","r":"[늡]"},{"l":"엿","r":"[엳]"}],"mis":"K1-2-u6-X10","explanation":["글자와 소리가 달라요.","밑[믿] · 늪[늡] · 엿[엳].","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#10','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',2,'match','auto','「달팽이의 길」에서 차례와 있었던 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「달팽이의 길」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"집을 지고 길을 나섰어요"},{"l":"가운데","r":"개미의 말에도 쉬지 않고 나아갔어요"},{"l":"끝","r":"커다란 버섯 아래에 닿았어요"}],"mis":"K1-2-u6-X17","explanation":["길을 나섬 → 쉬지 않음 → 닿음.","「저녁이 되자」.","줄 차례."],"asset":{"type":"passage","lines":["비 온 뒤 달팽이가 집을 지고 길을 나섰어요.","달팽이는 아주 천천히 풀잎을 기어올랐어요.","개미가 \"그렇게 느려서 언제 가니?\" 하고 물었어요.","달팽이는 쉬지 않고 한 걸음씩 나아갔어요.","저녁이 되자 달팽이는 커다란 버섯 아래에 닿았어요."],"title":"「달팽이의 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#11','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',2,'mc','auto','「그거 싫어.」라는 말을 들은 친구가 되물을 만한 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X02']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"「그거 싫어.」라는 말을 들은 친구가 되물을 만한 까닭은 무엇인가요?","options":[{"t":"무엇이 왜 싫은지 알 수 없어서","correct":true},{"t":"말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"목소리가 작아서","mis":"K1-2-u6-X02"}],"explanation":["무엇이, 왜가 빠졌어요.","길어서가 아니라 짧아서예요.","무엇을 왜."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#12','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',2,'mc','auto','「책꽂이에 책이 거꾸로 꽂혀 있어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「책꽂이에 책이 거꾸로 꽂혀 있어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"책 제목이 보이게 바로 꽂아요.","correct":true},{"t":"책꽂이를 비워 둬요.","mis":"K1-2-u6-X05"},{"t":"책을 바닥에 쌓아 둬요.","mis":"K1-2-u6-X05"}],"explanation":["바로 꽂으면 찾기 쉬워요.","비우거나 바닥에 쌓으면 더 엉망이에요.","지금 할 수 있는 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#13','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',2,'mc','auto','시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X08']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"나뭇잎이 모여 그늘이 되듯 우리 반도 서로 쉴 곳이 되어 줄 수 있을 것 같아요.","correct":true},{"t":"좋았어요.","mis":"K1-2-u6-X01"},{"t":"여름 나무 아래 시원한 그늘이 되어요.","mis":"K1-2-u6-X08"}],"explanation":["내 생각이 내 말로 드러나요.","한마디나 시를 옮긴 말은 생각이 아니에요.","「나도 ~」."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#14','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',2,'mc','auto','친구가 대사를 읽을 때 우리가 할 일은 무엇인가요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"친구가 대사를 읽을 때 우리가 할 일은 무엇인가요?","options":[{"t":"읽는 친구를 바라보며 귀 기울여 듣는다","correct":true},{"t":"틀린 곳에서 크게 웃는다","mis":"K1-2-u6-X19"},{"t":"내 대사만 혼자 연습한다","mis":"K1-2-u6-X19"}],"explanation":["귀 기울여 들어요.","웃거나 딴 일을 하면 안 돼요.","끝까지 들어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#15','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C5',2,'ox','auto','친구와 쉬는 곳이 달라도 뜻이 잘 통하면 괜찮아요.',ARRAY['K1-2-u6-X15']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"친구와 쉬는 곳이 달라도 뜻이 잘 통하면 괜찮아요.","answer":"O","reason_options":[{"t":"뜻이 이어지는 덩어리는 여러 가지로 묶을 수 있으니까","correct":true},{"t":"나와 같은 곳에서 쉬어야 맞으니까","mis":"K1-2-u6-X15"}],"mis":"K1-2-u6-X15","explanation":["둘 다 맞을 수 있어요.","뜻이 통하는지 들어 봐요.","다르다고 틀린 게 아니에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
