INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#17','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C5',3,'error','auto','(∨ 는 쉬어 읽는 곳이에요.) 친구들의 읽기를 모았어요.
