INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#19','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C2',3,'ox','auto','세 칸 생각은 문제를 먼저 쓰고 해결 방법, 자신의 생각 차례로 써요.',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"세 칸 생각은 문제를 먼저 쓰고 해결 방법, 자신의 생각 차례로 써요.","answer":"O","reason_options":[{"t":"무엇이 문제인지 알아야 방법과 생각이 이해되니까","correct":true},{"t":"차례는 아무렇게나 써도 같으니까","mis":"K1-2-u6-X06"}],"mis":"K1-2-u6-X06","explanation":["문제 → 해결 방법 → 자신의 생각.","차례가 바뀌면 이해하기 어려워요.","문제부터."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#20','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C6',3,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「비 온 뒤 달팽이가 집을 지고 길을 나섰어요.」를 「누가」 뒤에서 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「비 온 뒤 달팽이가 집을 지고 길을 나섰어요.」를 「누가」 뒤에서 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"비 온 뒤 달팽이가 ∨ 집을 지고 길을 나섰어요.","correct":true},{"t":"비 온 뒤 달팽 ∨ 이가 집을 지고 길을 나섰어요.","mis":"K1-2-u6-X13"},{"t":"비온뒤달팽이가집을지고길을나섰어요.","mis":"K1-2-u6-X14"}],"explanation":["「달팽이가」 뒤에서 쉬었어요.","낱말을 자르거나 붙이면 안 돼요.","누가 뒤에서 조금."],"asset":{"type":"passage","lines":["비 온 뒤 달팽이가 집을 지고 길을 나섰어요.","달팽이는 아주 천천히 풀잎을 기어올랐어요.","개미가 \"그렇게 느려서 언제 가니?\" 하고 물었어요.","달팽이는 쉬지 않고 한 걸음씩 나아갔어요.","저녁이 되자 달팽이는 커다란 버섯 아래에 닿았어요."],"title":"「달팽이의 길」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#21','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C7',3,'error','auto','문장 부호에 따라 읽는 법을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#22','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',3,'mc','auto','시 「나뭇잎」에 대해 바르게 말한 것은 어느 것인가요?',ARRAY['K1-2-u6-X09','K1-2-u6-X08']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「나뭇잎」에 대해 바르게 말한 것은 어느 것인가요?","options":[{"t":"혼자일 때는 춤추고, 함께일 때는 그늘이 되어 둘 다 소중하다","correct":true},{"t":"혼자 춤추는 나뭇잎은 쓸모가 없다","mis":"K1-2-u6-X09"},{"t":"나뭇잎이 모이면 춤을 못 춰서 슬프다","mis":"K1-2-u6-X08"}],"explanation":["혼자도 함께도 빛나요.","쓸모없다거나 슬프다는 말은 없어요.","둘 다 소중해요."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#23','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C8',4,'sa','auto','「뜨겁다」의 반대말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#24','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C1',4,'essay','teacher','그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 먼저 와서 기다린 친구들이 속상하니까 맨 뒤로 가서 줄을 서자. — 할 일과 까닭이 함께 있으면 맞아요.","scoring_points":["무엇을 어떻게 하자는지 있는가","까닭이 있는가","나무라지 않고 받아들이기 쉬운 말인가"]},"explanation":["할 일 + 까닭.","「하지 마」 대신 「~하자」.","친구가 고개를 끄덕일 말."],"asset":{"type":"scene","icon":"🍱","text":"급식실에서 한 친구가 줄 앞에 끼어들어요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_c#25','kor',1,2,'u6','','g1_2_kor_u6_review_c','unit_review','K1-2-u6-C3',4,'essay','teacher','「나뭇잎」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"「나뭇잎」을 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.","answer_guide":{"answer":"예: 나뭇잎 하나가 춤추는 모습이 귀여워요. 모이면 그늘이 되어요. 나는 쉬는 시간에 혼자 있는 친구에게 같이 놀자고 하겠어요. — 시에서 온 생각과 할 일이 짧은 문장으로 있으면 맞아요.","scoring_points":["시에서 온 생각이 내 말로 있는가","우리 반을 위한 할 일(무엇을·언제)이 있는가","짧은 문장 여러 개로 나누었는가"]},"explanation":["짧은 문장 여러 개.","시를 옮기지 말고 내 말로.","할 일은 구체적으로."],"asset":{"type":"passage","lines":["나뭇잎 하나가","바람을 타고 빙그르르 춤을 춰요","나뭇잎이 모이고 모여","여름 나무 아래 시원한 그늘이 되어요"],"title":"「나뭇잎」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#1','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',1,'mc','auto','그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X02']::text[],false,'{"seq":1,"concept":"K1-2-u6-C1","difficulty":1,"kind":"mc","stem":"그림 속 친구에게 느낌에서 한 걸음 더 나아가 해 주고 싶은 말은 어느 것인가요?","options":[{"t":"내려오는 친구와 부딪힐 수 있으니까 계단으로 올라가자.","correct":true},{"t":"무서워.","mis":"K1-2-u6-X01"},{"t":"안 돼.","mis":"K1-2-u6-X02"}],"explanation":["할 일과 까닭이 함께 있어요.","느낌만, 까닭 없는 말은 잘 통하지 않아요.","「~하니까 ~하자」."],"asset":{"type":"scene","icon":"🏃","text":"놀이터에서 한 친구가 미끄럼틀을 거꾸로 올라가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#2','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',1,'mc','auto','해린이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X06']::text[],false,'{"seq":2,"concept":"K1-2-u6-C2","difficulty":1,"kind":"mc","stem":"해린이의 세 칸 생각에서 「해결 방법」 칸에 쓴 것은 어느 것인가요?","options":[{"t":"현관에서 물기를 털고 우산꽂이에 꽂아요.","correct":true},{"t":"젖은 우산을 털지 않고 교실까지 들고 와요.","mis":"K1-2-u6-X06"},{"t":"교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요.","mis":"K1-2-u6-X06"}],"explanation":["둘째 칸이에요.","첫째는 문제, 셋째는 자신의 생각.","칸 이름을 짚어요."],"asset":{"type":"passage","lines":["문제: 젖은 우산을 털지 않고 교실까지 들고 와요.","해결 방법: 현관에서 물기를 털고 우산꽂이에 꽂아요.","자신의 생각: 교실 바닥이 미끄러워 넘어질 수 있으니까 현관에서 정리하면 좋겠어요."],"title":"해린이가 쓴 세 칸 생각"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#3','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',1,'mc','auto','이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?',ARRAY['K1-2-u6-X08']::text[],false,'{"seq":3,"concept":"K1-2-u6-C3","difficulty":1,"kind":"mc","stem":"이 시에서 하나가 혼자 있을 때의 모습을 그린 줄은 어느 것인가요?","options":[{"t":"내 손등에 살며시 내려앉아요","correct":true},{"t":"마당에 하얀 눈사람이 생겨요","mis":"K1-2-u6-X08"},{"t":"눈송이가 소복소복 쌓여","mis":"K1-2-u6-X08"}],"explanation":["눈송이 하나의 모습이에요.","눈사람은 모였을 때예요.","하나 / 모임을 나누어요."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#4','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C4',1,'mc','auto','[늡]이라고 소리 나는, 물이 고여 질척한 땅을 바르게 쓴 것은 어느 것인가요?',ARRAY['K1-2-u6-X10']::text[],false,'{"seq":4,"concept":"K1-2-u6-C4","difficulty":1,"kind":"mc","stem":"[늡]이라고 소리 나는, 물이 고여 질척한 땅을 바르게 쓴 것은 어느 것인가요?","options":[{"t":"늪","correct":true},{"t":"늡","mis":"K1-2-u6-X10"},{"t":"늣","mis":"K1-2-u6-X10"}],"explanation":["글자는 「늪」이에요.","소리대로 쓰지 않아요.","받침 ㅍ."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#5','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C5',1,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?',ARRAY['K1-2-u6-X14','K1-2-u6-X13']::text[],false,'{"seq":5,"concept":"K1-2-u6-C5","difficulty":1,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 더 자연스럽게 읽은 쪽은 어느 것인가요?","options":[{"t":"비가 오는 날에는 ∨ 실내화를 꼭 갈아 신어요.","correct":true},{"t":"비가오는날에는실내화를꼭갈아신어요.","mis":"K1-2-u6-X14"},{"t":"비가 오는 날에는 실 ∨ 내화를 꼭 갈 ∨ 아 신어요.","mis":"K1-2-u6-X13"}],"explanation":["덩어리로 묶어 읽었어요.","붙이거나 낱말을 자르면 안 돼요.","낱말은 한 덩어리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#6','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C6',1,'mc','auto','「커다란 구름은 마른 들판 위에 비를 뿌렸어요.」에서 「무엇이」에 해당하는 말은 어느 것인가요?',ARRAY['K1-2-u6-X16']::text[],false,'{"seq":6,"concept":"K1-2-u6-C6","difficulty":1,"kind":"mc","stem":"「커다란 구름은 마른 들판 위에 비를 뿌렸어요.」에서 「무엇이」에 해당하는 말은 어느 것인가요?","options":[{"t":"커다란 구름은","correct":true},{"t":"들판 위에","mis":"K1-2-u6-X16"},{"t":"비를","mis":"K1-2-u6-X16"}],"explanation":["비를 뿌린 것은 커다란 구름이에요.","들판 위는 어디에, 비는 무엇을이에요.","「무엇이?」 물어요."],"asset":{"type":"passage","lines":["하늘에 꼬마 구름 하나가 떠 있었어요.","꼬마 구름은 친구 구름들을 만나 점점 커졌어요.","커다란 구름은 마른 들판 위에 비를 뿌렸어요.","들판의 풀들이 고개를 들었어요.","해가 나오자 하늘에 무지개가 걸렸어요."],"title":"「꼬마 구름」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#7','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C7',1,'mc','auto','「정말? 우리 눈사람 만들까?」는 어떻게 읽나요?',ARRAY['K1-2-u6-X18']::text[],false,'{"seq":7,"concept":"K1-2-u6-C7","difficulty":1,"kind":"mc","stem":"「정말? 우리 눈사람 만들까?」는 어떻게 읽나요?","options":[{"t":"두 군데 모두 끝을 살짝 올려 읽는다","correct":true},{"t":"두 군데 모두 끝을 내려 읽는다","mis":"K1-2-u6-X18"},{"t":"힘주어 외치듯 읽는다","mis":"K1-2-u6-X18"}],"explanation":["물음표가 두 번 있어요.","둘 다 끝을 올려요.","? 올림."],"asset":{"type":"speech","turns":[{"who":"해설","text":"아침에 일어나니 창밖이 온통 하얬어요."},{"who":"동생","text":"언니, 눈이 왔어!"},{"who":"언니","text":"정말? 우리 눈사람 만들까?"},{"who":"엄마","text":"장갑부터 끼고 나가렴."},{"who":"해설","text":"둘은 손을 잡고 마당으로 달려 나갔어요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#8','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C8',1,'blank','auto','빈칸에 알맞은 말은 어느 것인가요?
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#9','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C4',2,'match','auto','낱말과 소리를 선으로 이어 보세요.','{}'::text[],false,'{"seq":9,"concept":"K1-2-u6-C4","difficulty":2,"kind":"match","stem":"낱말과 소리를 선으로 이어 보세요.","pairs":[{"l":"곁","r":"[겯]"},{"l":"붓","r":"[붇]"},{"l":"짚","r":"[집]"}],"mis":"K1-2-u6-X10","explanation":["글자와 소리가 달라요.","곁[겯] · 붓[붇] · 짚[집].","소리 내어 읽어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#10','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C6',2,'match','auto','「꼬마 구름」에서 차례와 있었던 일을 선으로 이어 보세요.','{}'::text[],false,'{"seq":10,"concept":"K1-2-u6-C6","difficulty":2,"kind":"match","stem":"「꼬마 구름」에서 차례와 있었던 일을 선으로 이어 보세요.","pairs":[{"l":"처음","r":"꼬마 구름 하나가 떠 있었어요"},{"l":"가운데","r":"친구 구름들을 만나 커졌어요"},{"l":"끝","r":"들판 위에 비를 뿌렸어요"}],"mis":"K1-2-u6-X17","explanation":["하나 → 커짐 → 비.","「점점」, 「커다란」.","줄 차례."],"asset":{"type":"passage","lines":["하늘에 꼬마 구름 하나가 떠 있었어요.","꼬마 구름은 친구 구름들을 만나 점점 커졌어요.","커다란 구름은 마른 들판 위에 비를 뿌렸어요.","들판의 풀들이 고개를 들었어요.","해가 나오자 하늘에 무지개가 걸렸어요."],"title":"「꼬마 구름」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#11','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',2,'mc','auto','「이상해.」라는 말을 들은 친구가 되물을 만한 까닭은 무엇인가요?',ARRAY['K1-2-u6-X07','K1-2-u6-X02']::text[],false,'{"seq":11,"concept":"K1-2-u6-C1","difficulty":2,"kind":"mc","stem":"「이상해.」라는 말을 들은 친구가 되물을 만한 까닭은 무엇인가요?","options":[{"t":"무엇이 왜 이상한지, 어떻게 하자는지 알 수 없어서","correct":true},{"t":"말이 너무 길어서","mis":"K1-2-u6-X07"},{"t":"웃으며 말해서","mis":"K1-2-u6-X02"}],"explanation":["느낌만 있어요.","무엇이 왜, 어떻게가 빠졌어요.","느낌에서 한 걸음 더."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#12','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',2,'mc','auto','「줄넘기 줄이 엉킨 채 상자에 들어 있어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?',ARRAY['K1-2-u6-X05']::text[],false,'{"seq":12,"concept":"K1-2-u6-C2","difficulty":2,"kind":"mc","stem":"「줄넘기 줄이 엉킨 채 상자에 들어 있어요.」라는 문제에 알맞은 해결 방법은 어느 것인가요?","options":[{"t":"다 쓰면 줄을 감아서 넣어요.","correct":true},{"t":"줄넘기를 하지 않아요.","mis":"K1-2-u6-X05"},{"t":"엉킨 줄을 버려요.","mis":"K1-2-u6-X05"}],"explanation":["감아 두면 엉키지 않아요.","안 하거나 버리는 것은 방법이 아니에요.","지금 할 수 있는 일."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#13','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',2,'mc','auto','시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?',ARRAY['K1-2-u6-X01','K1-2-u6-X08']::text[],false,'{"seq":13,"concept":"K1-2-u6-C3","difficulty":2,"kind":"mc","stem":"시를 읽고 생각을 나타낸 문장으로 가장 알맞은 것은 어느 것인가요?","options":[{"t":"작은 눈송이도 모이면 눈사람이 되니까, 나도 작은 일부터 친구들과 함께하고 싶어요.","correct":true},{"t":"좋았어요.","mis":"K1-2-u6-X01"},{"t":"마당에 하얀 눈사람이 생겨요.","mis":"K1-2-u6-X08"}],"explanation":["내 생각이 내 말로 드러나요.","한마디나 시를 옮긴 말은 생각이 아니에요.","「나도 ~」."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#14','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C7',2,'mc','auto','친구가 대사를 읽다 틀렸을 때 알맞은 것은 무엇인가요?',ARRAY['K1-2-u6-X19']::text[],false,'{"seq":14,"concept":"K1-2-u6-C7","difficulty":2,"kind":"mc","stem":"친구가 대사를 읽다 틀렸을 때 알맞은 것은 무엇인가요?","options":[{"t":"끝까지 조용히 듣고 다시 읽을 때 응원한다","correct":true},{"t":"바로 웃으며 흉내 낸다","mis":"K1-2-u6-X19"},{"t":"다른 친구로 바꾸자고 한다","mis":"K1-2-u6-X19"}],"explanation":["기다려 주고 응원해요.","흉내나 바꾸자는 말은 친구를 위축시켜요.","함께 만드는 연극."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#15','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C5',2,'ox','auto','낱말 가운데에서 쉬면 뜻이 끊어져요.',ARRAY['K1-2-u6-X13']::text[],false,'{"seq":15,"concept":"K1-2-u6-C5","difficulty":2,"kind":"ox","stem":"낱말 가운데에서 쉬면 뜻이 끊어져요.","answer":"O","reason_options":[{"t":"낱말이 잘려 무슨 말인지 알기 어려우니까","correct":true},{"t":"낱말 가운데가 숨 쉬기 가장 좋으니까","mis":"K1-2-u6-X13"}],"mis":"K1-2-u6-X13","explanation":["낱말은 통째로 읽어요.","가운데를 자르면 뜻이 끊겨요.","낱말은 한 덩어리."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
