INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#19','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C2',3,'ox','auto','「문제」 칸에는 글이나 그림에 없는 일을 지어내어 써도 돼요.',ARRAY['K1-2-u6-X04']::text[],false,'{"seq":19,"concept":"K1-2-u6-C2","difficulty":3,"kind":"ox","stem":"「문제」 칸에는 글이나 그림에 없는 일을 지어내어 써도 돼요.","answer":"X","reason_options":[{"t":"실제로 보이는 문제를 써야 해결 방법이 맞으니까","correct":true},{"t":"문제는 크게 부풀려야 눈에 띄니까","mis":"K1-2-u6-X04"}],"mis":"K1-2-u6-X04","explanation":["보이는 문제를 써요.","지어낸 문제엔 방법도 맞지 않아요.","그림·글에서 찾아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#20','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C6',3,'mc','auto','(∨ 는 쉬어 읽는 곳이에요.) 「꼬마 구름은 친구 구름들을 만나 점점 커졌어요.」를 「무엇이」 뒤에서 쉬어 읽은 것은 어느 것인가요?',ARRAY['K1-2-u6-X13','K1-2-u6-X14']::text[],false,'{"seq":20,"concept":"K1-2-u6-C6","difficulty":3,"kind":"mc","stem":"(∨ 는 쉬어 읽는 곳이에요.) 「꼬마 구름은 친구 구름들을 만나 점점 커졌어요.」를 「무엇이」 뒤에서 쉬어 읽은 것은 어느 것인가요?","options":[{"t":"꼬마 구름은 ∨ 친구 구름들을 만나 점점 커졌어요.","correct":true},{"t":"꼬마 구 ∨ 름은 친구 구름들을 만 ∨ 나 점점 커졌어요.","mis":"K1-2-u6-X13"},{"t":"꼬마구름은친구구름들을만나점점커졌어요.","mis":"K1-2-u6-X14"}],"explanation":["「꼬마 구름은」 뒤에서 쉬었어요.","낱말을 자르거나 붙이면 안 돼요.","무엇이 뒤에서 조금."],"asset":{"type":"passage","lines":["하늘에 꼬마 구름 하나가 떠 있었어요.","꼬마 구름은 친구 구름들을 만나 점점 커졌어요.","커다란 구름은 마른 들판 위에 비를 뿌렸어요.","들판의 풀들이 고개를 들었어요.","해가 나오자 하늘에 무지개가 걸렸어요."],"title":"「꼬마 구름」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#21','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C7',3,'error','auto','친구의 읽기에서 살펴볼 것을 모았어요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#22','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',3,'mc','auto','시 「눈송이」의 「마당에 하얀 눈사람이 생겨요」에서 알 수 있는 것은 무엇인가요?',ARRAY['K1-2-u6-X09','K1-2-u6-X08']::text[],false,'{"seq":22,"concept":"K1-2-u6-C3","difficulty":3,"kind":"mc","stem":"시 「눈송이」의 「마당에 하얀 눈사람이 생겨요」에서 알 수 있는 것은 무엇인가요?","options":[{"t":"작은 것도 모이면 큰 것이 될 수 있다","correct":true},{"t":"눈송이 하나는 금방 사라져 쓸모없다","mis":"K1-2-u6-X09"},{"t":"눈사람은 눈송이 한 송이로 만든다","mis":"K1-2-u6-X08"}],"explanation":["쌓인 눈송이가 눈사람이 되었어요.","하나도 손등에 앉는 제 모습이 있어요.","둘 다 소중해요."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#23','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C8',4,'sa','auto','「많다」의 반대말을 쓰세요.
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#24','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C1',4,'essay','teacher','그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"K1-2-u6-C1","difficulty":4,"kind":"essay","stem":"그림 속 친구에게 해 주고 싶은 말을, 무엇을 어떻게 하자는지와 그 까닭이 들어가게 한 문장으로 쓰세요.","answer_guide":{"answer":"예: 내려오는 친구와 부딪힐 수 있으니까 계단으로 올라가자. — 할 일과 까닭이 함께 있으면 맞아요.","scoring_points":["무엇을 어떻게 하자는지 있는가","까닭이 있는가","나무라지 않고 받아들이기 쉬운 말인가"]},"explanation":["할 일 + 까닭.","「하지 마」 대신 「~하자」.","친구가 고개를 끄덕일 말."],"asset":{"type":"scene","icon":"🏃","text":"놀이터에서 한 친구가 미끄럼틀을 거꾸로 올라가요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g1_2_kor_u6_review_d#25','kor',1,2,'u6','','g1_2_kor_u6_review_d','unit_review','K1-2-u6-C3',4,'essay','teacher','「눈송이」를 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.','{}'::text[],false,'{"seq":25,"concept":"K1-2-u6-C3","difficulty":4,"kind":"essay","stem":"「눈송이」를 읽고 떠오른 생각을 짧은 문장 두세 개로 쓰고, 우리 반을 위해 내가 할 일을 하나 넣으세요.","answer_guide":{"answer":"예: 눈송이 하나는 작아요. 모이면 눈사람이 돼요. 나는 청소 시간에 작은 쓰레기부터 하나씩 줍겠어요. — 시에서 온 생각과 할 일이 짧은 문장으로 있으면 맞아요.","scoring_points":["시에서 온 생각이 내 말로 있는가","우리 반을 위한 할 일(무엇을·언제)이 있는가","짧은 문장 여러 개로 나누었는가"]},"explanation":["짧은 문장 여러 개.","시를 옮기지 말고 내 말로.","할 일은 구체적으로."],"asset":{"type":"passage","lines":["눈송이 하나가","내 손등에 살며시 내려앉아요","눈송이가 소복소복 쌓여","마당에 하얀 눈사람이 생겨요"],"title":"「눈송이」"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
